      { from: 'o1', to: 'stakeholders', type: 'input' },
      { from: 't1', to: 'stakeholders', type: 'tool' },
      { from: 't2', to: 'stakeholders', type: 'tool' },
      { from: 'stakeholders', to: 'o6', type: 'output' },

      // Develop Project Management Plan
      { from: 'o1', to: 'plan', type: 'input' },
      { from: 'i3', to: 'plan', type: 'input' },
      { from: 'i4', to: 'plan', type: 'input' },
      { from: 't1', to: 'plan', type: 'tool' },
      { from: 't3', to: 'plan', type: 'tool' },
      { from: 'plan', to: 'o2', type: 'output' },

      // Collect Requirements
      { from: 'o1', to: 'requirements', type: 'input' },
      { from: 'o2', to: 'requirements', type: 'input' },
      { from: 'o6', to: 'requirements', type: 'input' },
      { from: 't1', to: 'requirements', type: 'tool' },
      { from: 't2', to: 'requirements', type: 'tool' },
      { from: 't4', to: 'requirements', type: 'tool' },
      { from: 'requirements', to: 'o7', type: 'output' },

      // Define Scope
      { from: 'o1', to: 'scope', type: 'input' },
      { from: 'o2', to: 'scope', type: 'input' },
      { from: 'o7', to: 'scope', type: 'input' },
      { from: 't1', to: 'scope', type: 'tool' },
      { from: 'scope', to: 'o8', type: 'output' },

      // Create WBS
      { from: 'o2', to: 'wbs', type: 'input' },
      { from: 'o8', to: 'wbs', type: 'input' },
      { from: 't1', to: 'wbs', type: 'tool' },
      { from: 't5', to: 'wbs', type: 'tool' },
      { from: 'wbs', to: 'o9', type: 'output' },

      // Direct and Manage Project Work
      { from: 'o2', to: 'direct', type: 'input' },
      { from: 'i3', to: 'direct', type: 'input' },
      { from: 'i4', to: 'direct', type: 'input' },
      { from: 't1', to: 'direct', type: 'tool' },
      { from: 'direct', to: 'o3', type: 'output' },
      { from: 'direct', to: 'o4', type: 'output' },
      { from: 'direct', to: 'o5', type: 'output' },

      // Process outputs feeding into other processes
      { from: 'o1', to: 'i5', type: 'flow' },
      { from: 'o6', to: 'i6', type: 'flow' },
      { from: 'o7', to: 'i7', type: 'flow' },
    ],
  }

  // Combine all nodes for easier access
  const allNodes = useMemo(() => {
    return [...ittoData.processes, ...ittoData.inputs, ...ittoData.tools, ...ittoData.outputs]
  }, [])

  // Get connected nodes for highlighting
  const getConnectedNodes = (nodeId) => {
    const connected = new Set()
    ittoData.connections.forEach((conn) => {
      if (conn.from === nodeId) {
        connected.add(conn.to)
      } else if (conn.to === nodeId) {
        connected.add(conn.from)
      }
    })
    return connected
  }

  // Handle window resize
  useEffect(() => {
    const handleResize = () => {
      if (svgRef.current) {
        const { width, height } = svgRef.current.getBoundingClientRect()
        setDimensions({ width, height })
      }
    }
    handleResize()
    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [])

  // Get node color based on type
  const getNodeColor = (node) => {
    if (node.type === 'input') return '#3B82F6' // blue
    if (node.type === 'tool') return '#10B981' // green
    if (node.type === 'output') return '#F59E0B' // amber
    if (node.group === 'Initiating') return '#8B5CF6' // violet
    if (node.group === 'Planning') return '#3B82F6' // blue
    if (node.group === 'Executing') return '#10B981' // green
    if (node.group === 'Monitoring & Controlling') return '#F59E0B' // amber
    if (node.group === 'Closing') return '#EF4444' // red
    return '#6B7280' // gray
  }

  // Get node shape component
  const getNodeShape = (node) => {
    if (node.type === 'input') return Circle
    if (node.type === 'tool') return Square
    if (node.type === 'output') return Triangle
    return Circle
  }

  // Calculate path for connections with curves
  const calculatePath = (from, to) => {
    const fromNode = allNodes.find((n) => n.id === from)
    const toNode = allNodes.find((n) => n.id === to)

    if (!fromNode || !toNode) return ''

    const dx = toNode.position.x - fromNode.position.x
    const dy = toNode.position.y - fromNode.position.y
    const dr = Math.sqrt(dx * dx + dy * dy)

    return `M ${fromNode.position.x} ${fromNode.position.y} A ${dr},${dr} 0 0,1 ${toNode.position.x} ${toNode.position.y}`
  }

  // Handle mouse wheel for zoom
  const handleWheel = (e) => {
    e.preventDefault()
    const delta = e.deltaY > 0 ? 0.9 : 1.1
    setZoom((prev) => Math.max(0.5, Math.min(2, prev * delta)))
  }

  // Handle drag for pan
  const handleMouseDown = (e) => {
    if (e.target === svgRef.current) {
      const startX = e.clientX - pan.x
      const startY = e.clientY - pan.y

      const handleMouseMove = (e) => {
        setPan({
          x: e.clientX - startX,
          y: e.clientY - startY,
        })
      }

      const handleMouseUp = () => {
        document.removeEventListener('mousemove', handleMouseMove)
        document.removeEventListener('mouseup', handleMouseUp)
      }

      document.addEventListener('mousemove', handleMouseMove)
      document.addEventListener('mouseup', handleMouseUp)
    }
  }

  const connectedNodes = hoveredNode ? getConnectedNodes(hoveredNode) : new Set()

  return (
    <div className="relative h-screen w-full overflow-hidden bg-gray-50">
      <div className="absolute left-4 top-4 z-10 rounded-lg bg-white p-4 shadow-lg">
        <h2 className="mb-2 text-lg font-bold">PMBOK ITTO Network Diagram</h2>
        <div className="space-y-2 text-sm">
          <div className="flex items-center space-x-2">
            <Circle className="h-4 w-4 text-blue-500" />
            <span>Inputs / Process (Initiating)</span>
          </div>
          <div className="flex items-center space-x-2">
            <Square className="h-4 w-4 text-green-500" />
            <span>Tools & Techniques</span>
          </div>
          <div className="flex items-center space-x-2">
            <Triangle className="h-4 w-4 text-amber-500" />
            <span>Outputs</span>
          </div>
          <div className="mt-2 border-t pt-2">
            <p className="text-xs text-gray-600">Scroll to zoom, drag to pan</p>
            <p className="text-xs text-gray-600">Click nodes for details</p>
          </div>
        </div>
      </div>

      <svg
        ref={svgRef}
        width="100%"
        height="100%"
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        style={{ cursor: 'grab' }}
      >
        <defs>
          <marker
            id="arrowhead"
            markerWidth="10"
            markerHeight="7"
            refX="9"
            refY="3.5"
            orient="auto"
          >
            <polygon points="0 0, 10 3.5, 0 7" fill="#6B7280" />
          </marker>
          <filter id="glow">
            <feGaussianBlur stdDeviation="3" result="coloredBlur" />
            <feMerge>
              <feMergeNode in="coloredBlur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>

        <g transform={`translate(${pan.x}, ${pan.y}) scale(${zoom})`}>
          {/* Render connections */}
          {ittoData.connections.map((conn, idx) => {
            const isHighlighted =
              hoveredNode && (conn.from === hoveredNode || conn.to === hoveredNode)
            const fromNode = allNodes.find((n) => n.id === conn.from)
            const toNode = allNodes.find((n) => n.id === conn.to)

            if (!fromNode || !toNode) return null

            return (
              <g key={idx}>
                <line
                  x1={fromNode.position.x}
                  y1={fromNode.position.y}
                  x2={toNode.position.x}
                  y2={toNode.position.y}
                  stroke={isHighlighted ? '#3B82F6' : '#E5E7EB'}
                  strokeWidth={isHighlighted ? 3 : 2}
                  markerEnd="url(#arrowhead)"
                  opacity={hoveredNode && !isHighlighted ? 0.2 : 1}
                  style={{
                    transition: 'all 0.3s ease',
                    filter: isHighlighted ? 'url(#glow)' : 'none',
                  }}
                >
                  {isHighlighted && (
                    <animate
                      attributeName="stroke-dasharray"
                      values="0,5;5,5"
                      dur="0.5s"
                      repeatCount="indefinite"
                    />
                  )}
                </line>
              </g>
            )
          })}

          {/* Render nodes */}
          {allNodes.map((node) => {
            const isHighlighted = hoveredNode === node.id || connectedNodes.has(node.id)
            //             const NodeShape = getNodeShape(node) // TODO: Will be used in future
            const color = getNodeColor(node)

            return (
              <g
                key={node.id}
                transform={`translate(${node.position.x}, ${node.position.y})`}
                className="cursor-pointer"
                onClick={() => setSelectedNode(node)}
                onMouseEnter={() => setHoveredNode(node.id)}
                onMouseLeave={() => setHoveredNode(null)}
                opacity={hoveredNode && !isHighlighted && hoveredNode !== node.id ? 0.3 : 1}
                style={{ transition: 'all 0.3s ease' }}
              >
                <circle
                  r={isHighlighted ? 35 : 30}
                  fill="white"
                  stroke={color}
                  strokeWidth={isHighlighted ? 4 : 2}
                  filter={isHighlighted ? 'url(#glow)' : 'none'}
                />
                {node.type === 'input' && <Circle x={-12} y={-12} size={24} color={color} />}
                {node.type === 'tool' && <Square x={-12} y={-12} size={24} color={color} />}
                {node.type === 'output' && <Triangle x={-12} y={-12} size={24} color={color} />}
                {!node.type && <Circle x={-12} y={-12} size={24} color={color} fill={color} />}
                <text
                  y={45}
                  textAnchor="middle"
                  className="pointer-events-none text-xs font-medium"
                  fill="#374151"
                >
                  {node.name.length > 20 ? node.name.substring(0, 20) + '...' : node.name}
                </text>
              </g>
            )
          })}
        </g>
      </svg>

      {/* Node details modal */}
      {selectedNode && (
        <div className="absolute bottom-4 right-4 z-10 max-w-md rounded-lg bg-white p-6 shadow-xl">
          <div className="mb-4 flex items-start justify-between">
            <h3 className="text-lg font-bold">{selectedNode.name}</h3>
            <button
              onClick={() => setSelectedNode(null)}
              className="text-gray-400 hover:text-gray-600"
            >
              ×
            </button>
          </div>

          <div className="space-y-2 text-sm">
            {selectedNode.type && (
              <p>
                <span className="font-semibold">Type:</span>{' '}
                {selectedNode.type.charAt(0).toUpperCase() + selectedNode.type.slice(1)}
              </p>
            )}
            {selectedNode.group && (
              <p>
                <span className="font-semibold">Process Group:</span> {selectedNode.group}
              </p>
            )}
            {selectedNode.area && (
              <p>
                <span className="font-semibold">Knowledge Area:</span> {selectedNode.area}
              </p>
            )}

            <div className="mt-4 border-t pt-4">
              <p className="flex items-center text-xs text-gray-600">
                <Info className="mr-1 h-4 w-4" />
                Click other nodes to explore relationships
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

export default ITTONetworkDiagram

import React, { useEffect, useRef, useState, useMemo } from 'react'
import * as d3 from 'd3'
import {
  sankey,
  sankeyLinkHorizontal,
  sankeyLeft,
  sankeyRight,
  sankeyCenter,
  sankeyJustify,
} from 'd3-sankey'
import {
  Download,
  _Settings,
  Palette,
  AlignLeft,
  AlignRight,
  AlignCenter,
  AlignJustify,
} from 'lucide-react'

const SankeyDiagram = ({ data }) => {
  const svgRef = useRef(null)
  const containerRef = useRef(null)
  const [selectedTheme, setSelectedTheme] = useState('default')
  const [selectedAlignment, setSelectedAlignment] = useState('justify')
  const [nodeWidth, setNodeWidth] = useState(15)
  const [nodePadding, setNodePadding] = useState(10)
  const [dimensions, setDimensions] = useState({ width: 1200, height: 800 })
  const [hoveredNode, setHoveredNode] = useState(null)
  const [hoveredLink, setHoveredLink] = useState(null)

  // カラーテーマ
  const themes = {
    default: {
      name: 'デフォルト',
      processGroup: {
        立ち上げ: '#8B5CF6',
        計画: '#3B82F6',
        実行: '#10B981',
        '監視・コントロール': '#F59E0B',
        終結: '#EF4444',
      },
      link: '#e0e0e0',
      linkHover: '#999',
      text: '#333',
      background: '#f9fafb',
    },
    ocean: {
      name: 'オーシャン',
      processGroup: {
        立ち上げ: '#0891b2',
        計画: '#0e7490',
        実行: '#155e75',
        '監視・コントロール': '#164e63',
        終結: '#134e4a',
      },
      link: '#cbd5e1',
      linkHover: '#64748b',
      text: '#1e293b',
      background: '#f0f9ff',
    },
    sunset: {
      name: 'サンセット',
      processGroup: {
        立ち上げ: '#f97316',
        計画: '#ea580c',
        実行: '#dc2626',
        '監視・コントロール': '#b91c1c',
        終結: '#991b1b',
      },
      link: '#fed7aa',
      linkHover: '#fb923c',
      text: '#451a03',
      background: '#fff7ed',
    },
  }

  // アラインメントオプション
  const alignments = {
    left: { name: '左寄せ', icon: AlignLeft, func: sankeyLeft },
    right: { name: '右寄せ', icon: AlignRight, func: sankeyRight },
    center: { name: '中央', icon: AlignCenter, func: sankeyCenter },
    justify: { name: '均等', icon: AlignJustify, func: sankeyJustify },
  }

  // レスポンシブ対応
  useEffect(() => {
    const updateDimensions = () => {
      if (containerRef.current) {
        const { width, height } = containerRef.current.getBoundingClientRect()
        setDimensions({
          width: width || 1200,
          height: height || 800,
        })
      }
    }

    updateDimensions()
    window.addEventListener('resize', updateDimensions)
    return () => window.removeEventListener('resize', updateDimensions)
  }, [])

  // サンキーデータの準備
  const sankeyData = useMemo(() => {
    if (!data) return null

    // ノードの作成（プロセス群とプロセス）
    const nodes = []
    const nodeMap = new Map()
    let nodeIndex = 0

    // プロセス群ノード
    const processGroups = ['立ち上げ', '計画', '実行', '監視・コントロール', '終結']
    processGroups.forEach((group) => {
      const node = { id: `pg_${group}`, name: group, type: 'processGroup', index: nodeIndex++ }
      nodes.push(node)
      nodeMap.set(node.id, node)
    })

    // プロセスノード（知識エリア別にグループ化）
    const processNodes = data.nodes.filter((n) => n.type === 'process')
    const knowledgeAreas = [...new Set(processNodes.map((p) => p.area))]

    knowledgeAreas.forEach((area) => {
      const areaProcesses = processNodes.filter((p) => p.area === area)
      areaProcesses.forEach((process) => {
        const node = {
          id: process.id,
          name: process.name,
          type: 'process',
          area: process.area,
          group: process.group,
          index: nodeIndex++,
        }
        nodes.push(node)
        nodeMap.set(node.id, node)
      })
    })

    // アウトプットノード（主要なもののみ）
    const majorOutputs = [
      'プロジェクト憲章',
      'プロジェクトマネジメント計画書',
      '成果物',
      '作業パフォーマンス・データ',
      '作業パフォーマンス報告書',
      '変更要求',
      '最終報告書',
    ]

    majorOutputs.forEach((outputName) => {
      const outputNode = data.nodes.find((n) => n.type === 'output' && n.name === outputName)
      if (outputNode) {
        const node = {
          id: outputNode.id,
          name: outputNode.name,
          type: 'output',
          index: nodeIndex++,
        }
        nodes.push(node)
        nodeMap.set(node.id, node)
      }
    })

    // リンクの作成
    const links = []

    // プロセス群からプロセスへのリンク
    processNodes.forEach((process) => {
      const sourceId = `pg_${process.group}`
      if (nodeMap.has(sourceId) && nodeMap.has(process.id)) {
        links.push({
          source: nodeMap.get(sourceId).index,
          target: nodeMap.get(process.id).index,
          value: 1,
          type: 'group-to-process',
        })
      }
    })

    // プロセスからアウトプットへのリンク
    data.links.forEach((link) => {
      if (link.type === 'output') {
        const sourceNode = nodeMap.get(link.source.id || link.source)
        const targetNode = nodeMap.get(link.target.id || link.target)
        if (sourceNode && targetNode && targetNode.type === 'output') {
          links.push({
            source: sourceNode.index,
            target: targetNode.index,
            value: 1,
            type: 'process-to-output',
            originalLink: link,
          })
        }
      }
    })

    return { nodes, links }
  }, [data])

  // サンキーダイアグラムの描画
  useEffect(() => {
    if (!sankeyData || !svgRef.current) return

    const theme = themes[selectedTheme]
    const margin = { top: 40, right: 150, bottom: 40, left: 150 }
    const width = dimensions.width - margin.left - margin.right
    const height = dimensions.height - margin.top - margin.bottom

    // SVGのクリア
    const svg = d3.select(svgRef.current)
    svg.selectAll('*').remove()

    // 背景色設定
    svg.style('background-color', theme.background)

    // グループの作成
    const g = svg.append('g').attr('transform', `translate(${margin.left},${margin.top})`)

    // サンキージェネレータの設定
    const sankeyGenerator = sankey()
      .nodeId((d) => d.index)
      .nodeAlign(alignments[selectedAlignment].func)
      .nodeWidth(nodeWidth)
      .nodePadding(nodePadding)
      .extent([
        [0, 0],
        [width, height],
      ])

    // データの処理
    const graph = sankeyGenerator({
      nodes: sankeyData.nodes.map((d) => ({ ...d })),
      links: sankeyData.links.map((d) => ({ ...d })),
    })

    // リンクの描画
    const link = g
      .append('g')
      .attr('fill', 'none')
      .selectAll('g')
      .data(graph.links)
      .join('g')
      .style('mix-blend-mode', 'multiply')

    link
      .append('path')
      .attr('d', sankeyLinkHorizontal())
      .attr('stroke', (d) => {
        if (d.type === 'group-to-process') {
          const targetNode = graph.nodes[d.target]
          return theme.processGroup[targetNode.group] || theme.link
        }
        return theme.link
      })
      .attr('stroke-width', (d) => Math.max(1, d.width))
      .attr('opacity', 0.5)
      .on('mouseenter', function (event, d) {
        setHoveredLink(d)
        d3.select(this).attr('stroke', theme.linkHover).attr('opacity', 0.8)
      })
      .on('mouseleave', function (event, d) {
        setHoveredLink(null)
        d3.select(this)
          .attr(
            'stroke',
            d.type === 'group-to-process'
              ? theme.processGroup[graph.nodes[d.target].group] || theme.link
              : theme.link
          )
          .attr('opacity', 0.5)
      })

    // ノードの描画
    const node = g.append('g').selectAll('g').data(graph.nodes).join('g')

    node
      .append('rect')
      .attr('x', (d) => d.x0)
      .attr('y', (d) => d.y0)
      .attr('height', (d) => d.y1 - d.y0)
      .attr('width', (d) => d.x1 - d.x0)
      .attr('fill', (d) => {
        if (d.type === 'processGroup') {
          return theme.processGroup[d.name]
        } else if (d.type === 'process') {
          return d3.color(theme.processGroup[d.group]).brighter(0.5)
        } else {
          return '#94a3b8'
        }
      })
      .attr('stroke', (d) =>
        d3
          .color(
            d.type === 'processGroup'
              ? theme.processGroup[d.name]
              : d.type === 'process'
                ? theme.processGroup[d.group]
                : '#64748b'
          )
          .darker(0.5)
      )
      .attr('stroke-width', 1)
      .on('mouseenter', function (event, d) {
        setHoveredNode(d)
        d3.select(this).attr('opacity', 0.8)
      })
      .on('mouseleave', function () {
        setHoveredNode(null)
        d3.select(this).attr('opacity', 1)
      })

    // ノードラベルの描画
    node
      .append('text')
      .attr('x', (d) => (d.x0 < width / 2 ? d.x1 + 6 : d.x0 - 6))
      .attr('y', (d) => (d.y1 + d.y0) / 2)
      .attr('dy', '0.35em')
      .attr('text-anchor', (d) => (d.x0 < width / 2 ? 'start' : 'end'))
      .attr('font-size', (d) => (d.type === 'processGroup' ? '14px' : '12px'))
      .attr('font-weight', (d) => (d.type === 'processGroup' ? 'bold' : 'normal'))
      .attr('fill', theme.text)
      .text((d) => d.name)
      .append('tspan')
      .attr('fill', '#666')
      .attr('font-size', '10px')
      .attr('dy', '1.2em')
      .attr('x', (d) => (d.x0 < width / 2 ? d.x1 + 6 : d.x0 - 6))
      .text((d) => (d.type === 'process' ? `(${d.area})` : ''))

    // タイトル
    svg
      .append('text')
      .attr('x', dimensions.width / 2)
      .attr('y', 20)
      .attr('text-anchor', 'middle')
      .attr('font-size', '18px')
      .attr('font-weight', 'bold')
      .attr('fill', theme.text)
      .text('PMBOKプロセスフロー サンキーダイアグラム')
  }, [sankeyData, dimensions, selectedTheme, selectedAlignment, nodeWidth, nodePadding])

  // SVGエクスポート
  const exportSVG = () => {
    const svgElement = svgRef.current
    const svgData = new XMLSerializer().serializeToString(svgElement)
    const blob = new Blob([svgData], { type: 'image/svg+xml' })
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = 'pmbok-sankey-diagram.svg'
    link.click()
    URL.revokeObjectURL(url)
  }

  return (
    <div ref={containerRef} className="relative h-full w-full bg-gray-50">
      {/* コントロールパネル */}
      <div className="absolute right-4 top-4 max-w-xs space-y-4 rounded-lg bg-white p-4 shadow-lg">
        <div>
          <label className="mb-2 block text-sm font-medium text-gray-700">カラーテーマ</label>
          <select
            value={selectedTheme}
            onChange={(e) => setSelectedTheme(e.target.value)}
