/**
 * API Client Configuration for PMP Learning Management System
 * Provides unified API client with authentication, error handling, and caching
 */

import { createTRPCReact } from '@trpc/react-query'
import { createTRPCMsw } from 'msw-trpc'
import { httpBatchLink, loggerLink } from '@trpc/client'
import { QueryClient, QueryCache } from '@tanstack/react-query'
import superjson from 'superjson'
import type { AppRouter } from '../trpc/server'
import { logger } from '../../services/logger'

// Create tRPC React hooks
export const api = createTRPCReact<AppRouter>()

// Create MSW handler for testing
export const trpcMsw = createTRPCMsw<AppRouter>()

// Base URL configuration
const getBaseUrl = () => {
  if (typeof window !== 'undefined') return '' // browser should use relative url
  if (process.env.VERCEL_URL) return `https://${process.env.VERCEL_URL}` // Vercel
  return `http://localhost:${process.env.PORT ?? 3000}` // dev SSR should use localhost
}

// Query client configuration with error handling
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 5 * 60 * 1000, // 5 minutes
      cacheTime: 10 * 60 * 1000, // 10 minutes
      retry: (failureCount, error) => {
        // Don't retry on 4xx errors
        if (error?.data?.httpStatus >= 400 && error?.data?.httpStatus < 500) {
          return false
        }
        return failureCount < 3
      },
      refetchOnWindowFocus: false,
    },
    mutations: {
      retry: 1,
    },
  },
  queryCache: new QueryCache({
    onError: (error, query) => {
      if (process.env.NODE_ENV === 'development') {
        logger.error(`Query error for key ${query.queryKey}:`, error)
      }
    },
  }),
})

// tRPC client configuration
export const trpcClient = api.createClient({
  transformer: superjson,
  links: [
    loggerLink({
      enabled: (opts) =>
        process.env.NODE_ENV === 'development' ||
        (opts.direction === 'down' && opts.result instanceof Error),
    }),
    httpBatchLink({
      url: `${getBaseUrl()}/api/trpc`,
      // You can pass any HTTP headers here
      async headers() {
        const headers: Record<string, string> = {}

        // Add auth token if available
        if (typeof window !== 'undefined') {
          const token = localStorage.getItem('auth-token')
          if (token) {
            headers['Authorization'] = `Bearer ${token}`
          }
        }

        return headers
      },
    }),
  ],
})

// API Error types
export interface ApiError {
  message: string
  code: string
  status: number
  details?: unknown
}

// API Response wrapper
export interface ApiResponse<T = unknown> {
  data?: T
  error?: ApiError
  success: boolean
  message?: string
}

// Utility function to handle API errors
export const handleApiError = (error: unknown): ApiError => {
  if (error instanceof Error) {
    return {
      message: error.message,
      code: 'UNKNOWN_ERROR',
      status: 500,
      details: error,
    }
  }

  if (typeof error === 'object' && error !== null && 'data' in error) {
    const trpcError = error as any
    return {
      message: trpcError.message || 'An error occurred',
      code: trpcError.data?.code || 'UNKNOWN_ERROR',
      status: trpcError.data?.httpStatus || 500,
      details: trpcError.data,
    }
  }

  return {
    message: 'An unexpected error occurred',
    code: 'UNKNOWN_ERROR',
    status: 500,
    details: error,
  }
}

// Cache invalidation helpers
export const invalidateQueries = {
  exam: () => queryClient.invalidateQueries({ queryKey: ['exam'] }),
  progress: () => queryClient.invalidateQueries({ queryKey: ['progress'] }),
  flashcards: () => queryClient.invalidateQueries({ queryKey: ['flashcards'] }),
  pmbok: () => queryClient.invalidateQueries({ queryKey: ['pmbok'] }),
  collaboration: () => queryClient.invalidateQueries({ queryKey: ['collaboration'] }),
  user: () => queryClient.invalidateQueries({ queryKey: ['user'] }),
  all: () => queryClient.invalidateQueries(),
}

// Offline support utilities
export const offlineUtils = {
  isOnline: () => typeof window !== 'undefined' && navigator.onLine,

  queueMutation: (mutation: string, data: unknown) => {
    if (typeof window !== 'undefined') {
      const queue = JSON.parse(localStorage.getItem('offline-mutations') || '[]')
      queue.push({ mutation, data, timestamp: Date.now() })
      localStorage.setItem('offline-mutations', JSON.stringify(queue))
    }
  },

  processPendingMutations: async () => {
    if (typeof window !== 'undefined' && offlineUtils.isOnline()) {
      const queue = JSON.parse(localStorage.getItem('offline-mutations') || '[]')

      for (const item of queue) {
        try {
          // Process queued mutations
          if (process.env.NODE_ENV === 'development') {
            logger.debug('Processing offline mutation:', item)
          }
          // Implementation would depend on specific mutation types
        } catch (error) {
          if (process.env.NODE_ENV === 'development') {
            logger.error('Failed to process offline mutation:', error)
          }
        }
      }

      // Clear processed mutations
      localStorage.setItem('offline-mutations', '[]')
    }
  },
}

// Performance monitoring
export const performanceUtils = {
  measureApiCall: (name: string) => {
    if (typeof window !== 'undefined' && 'performance' in window) {
      const start = performance.now()

      return {
        end: () => {
          const duration = performance.now() - start
          if (process.env.NODE_ENV === 'development') {
            logger.debug(`API call ${name} took ${duration.toFixed(2)}ms`)
          }

          // Report to analytics if configured
          if (window.gtag) {
            window.gtag('event', 'api_call_duration', {
              event_category: 'Performance',
              event_label: name,
              value: Math.round(duration),
            })
          }
        },
      }
    }

    return { end: () => {} }
  },
}

export default api

import { NextAuthOptions } from 'next-auth'
import { PrismaAdapter } from '@auth/prisma-adapter'
import GoogleProvider from 'next-auth/providers/google'
import CredentialsProvider from 'next-auth/providers/credentials'
import bcrypt from 'bcryptjs'
import { prisma } from '@/lib/db'
import type { _User } from '@prisma/client'
import { logger } from '../services/logger'

declare module 'next-auth' {
  interface Session {
    user: {
      id: string
      email: string
      name: string | null
      image: string | null
      role: string
    }
  }
}

declare module 'next-auth/jwt' {
  interface JWT {
    id: string
    role: string
  }
}

export const authOptions: NextAuthOptions = {
  adapter: PrismaAdapter(prisma) as any,
  session: {
    strategy: 'jwt',
    maxAge: 30 * 24 * 60 * 60, // 30 days
  },
  pages: {
    signIn: '/auth/login',
    signOut: '/auth/logout',
    error: '/auth/error',
    verifyRequest: '/auth/verify',
    newUser: '/dashboard',
  },
  providers: [
    GoogleProvider({
      clientId: process.env.GOOGLE_CLIENT_ID!,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET!,
      authorization: {
        params: {
          prompt: 'consent',
          access_type: 'offline',
          response_type: 'code',
        },
      },
    }),
    CredentialsProvider({
      name: 'credentials',
      credentials: {
        email: { label: 'Email', type: 'email' },
        password: { label: 'Password', type: 'password' },
      },
      async authorize(credentials) {
        if (!credentials?.email || !credentials?.password) {
          throw new Error('メールアドレスとパスワードを入力してください')
        }

        const user = await prisma.user.findUnique({
          where: { email: credentials.email },
          select: {
            id: true,
            email: true,
            name: true,
            image: true,
            role: true,
            password: true,
          },
        })

        if (!user || !user.password) {
          throw new Error('メールアドレスまたはパスワードが正しくありません')
        }

        const isPasswordValid = await bcrypt.compare(credentials.password, user.password)

        if (!isPasswordValid) {
          throw new Error('メールアドレスまたはパスワードが正しくありません')
        }

        return {
          id: user.id,
          email: user.email,
          name: user.name,
          image: user.image,
          role: user.role,
        }
      },
    }),
  ],
  callbacks: {
    async jwt({ token, user, account }) {
      if (user) {
        token.id = user.id
        token.role = (user as any).role || 'USER'
      }

      // Refresh access token for OAuth providers
      if (account?.provider === 'google') {
        token.accessToken = account.access_token
        token.refreshToken = account.refresh_token
        token.accessTokenExpires = account.expires_at
      }

      return token
    },
    async session({ session, token }) {
      if (session.user) {
        session.user.id = token.id as string
        session.user.role = token.role as string
      }
      return session
    },
    async signIn({ user, account, _profile }) {
      // Allow OAuth sign in without email verification
      if (account?.provider !== 'credentials') {
        return true
      }

      // For credentials provider, check if email is verified
      const existingUser = await prisma.user.findUnique({
        where: { email: user.email! },
      })

      if (!existingUser?.emailVerified) {
        // You can redirect to email verification page
        return '/auth/verify-email'
      }

      return true
    },
  },
  events: {
    async signIn({ user, account, _isNewUser }) {
      // Log sign in event
      if (process.env.NODE_ENV === 'development') {
        logger.debug(`User ${user.email} signed in via ${account?.provider}`)
      }

      // Track user activity
      if (user.id) {
        await prisma.user.update({
          where: { id: user.id },
          data: { lastLogin: new Date() },
        })
      }
    },
    async signOut({ _session, _token }) {
      // Log sign out event
      if (process.env.NODE_ENV === 'development') {
        logger.debug(`User signed out`)
      }
    },
    async createUser({ user }) {
      // Send welcome email
      if (process.env.NODE_ENV === 'development') {
        logger.debug(`New user created: ${user.email}`)
      }

      // Initialize user progress
      const pmbokProcesses = await prisma.pMBOKProcess.findMany()

      if (pmbokProcesses.length > 0) {
        await prisma.learningProgress.createMany({
          data: pmbokProcesses.map((process) => ({
            userId: user.id,
            processId: process.id,
            status: 'NOT_STARTED',
            masteryLevel: 0,
            totalStudyTime: 0,
          })),
        })
      }
    },
  },
  debug: process.env.NODE_ENV === 'development',
}

/**
 * Wrapper for getServerSession to use with our auth options
 */
import { getServerSession as getNextAuthServerSession } from 'next-auth'

export async function getServerSession() {
  return await getNextAuthServerSession(authOptions)
}

/**
 * Wrapper for protecting API routes
 */
export async function getAuthenticatedUser() {
  const session = await getServerSession()

  if (!session?.user?.id) {
    throw new Error('Unauthorized')
  }

  return session.user
}

/**
 * Check if user has required role
 */
export async function requireRole(requiredRole: 'USER' | 'PREMIUM' | 'ADMIN') {
  const user = await getAuthenticatedUser()

  const roleHierarchy = {
    USER: 0,
    PREMIUM: 1,
    ADMIN: 2,
  }

  if (roleHierarchy[user.role as keyof typeof roleHierarchy] < roleHierarchy[requiredRole]) {
    throw new Error('Insufficient permissions')
  }

  return user
}

