 */
export function geoLocationMiddleware() {
  return async (req: Request, res: Response, next: NextFunction) => {
    try {
      // クライアントIPを取得
      const clientIP = getClientIP(req)

      // GeoIP情報取得
      const geoLocation = await geoIPService.getGeoLocation(clientIP)

      if (geoLocation) {
        req.geoLocation = {
          ip: geoLocation.ip,
          country: geoLocation.country,
          countryCode: geoLocation.countryCode,
          region: geoLocation.region,
          city: geoLocation.city,
          threat: geoLocation.threat,
          proxy: geoLocation.proxy,
          vpn: geoLocation.vpn,
          tor: geoLocation.tor,
          hosting: geoLocation.hosting,
        }

        // レスポンスヘッダーに地理情報を追加（デバッグ用）
        if (process.env.NODE_ENV === 'development') {
          res.setHeader('X-Geo-Country', geoLocation.countryCode)
          res.setHeader('X-Geo-City', geoLocation.city || 'Unknown')
          res.setHeader('X-Geo-Threat', geoLocation.threat.toString())
        }
      }

      next()
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('GeoLocation middleware error:', error)
      }
      // エラーが発生してもリクエストは続行
      next()
    }
  }
}

/**
 * 地理的制限ミドルウェア
 */
export function geoRestrictionMiddleware(config: GeoRestrictionConfig) {
  return async (req: Request, res: Response, next: NextFunction) => {
    try {
      const clientIP = getClientIP(req)

      // 地理的制限チェック
      const restrictionResult = await geoIPService.checkGeoRestrictions(clientIP, config)

      req.geoRestriction = {
        allowed: restrictionResult.allowed,
        reason: restrictionResult.reason,
        riskScore: restrictionResult.location?.threat || 0,
      }

      if (!restrictionResult.allowed) {
        // 制限された場合のログ記録
        if (process.env.NODE_ENV === 'development') {
          logger.warn(`Geo-restricted access blocked: ${clientIP} - ${restrictionResult.reason}`)
        }

        return res.status(403).json({
          error: 'Access denied',
          message: 'Your location is not permitted to access this service',
          code: 'GEO_RESTRICTED',
          details: process.env.NODE_ENV === 'development' ? restrictionResult.reason : undefined,
        })
      }

      next()
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Geo restriction middleware error:', error)
      }

      // エラー時は安全側に倒す（本番環境での設定による）
      if (process.env.GEO_RESTRICTION_FAIL_SECURE === 'true') {
        return res.status(503).json({
          error: 'Service unavailable',
          message: 'Geographic verification is temporarily unavailable',
          code: 'GEO_SERVICE_ERROR',
        })
      }

      next()
    }
  }
}

/**
 * 異常アクセスパターン検知ミドルウェア
 */
export function anomalyDetectionMiddleware() {
  return async (req: Request, res: Response, next: NextFunction) => {
    try {
      // 認証済みユーザーのみチェック
      const userId = (req as any).user?.id || (req as any).session?.userId
      if (!userId) {
        return next()
      }

      const clientIP = getClientIP(req)

      // 異常パターン検知
      const anomalyResult = await geoIPService.detectAnomalousPatterns(userId, clientIP)

      if (anomalyResult.isAnomalous && anomalyResult.confidence > 80) {
        // 高信頼度の異常パターンを検知
        if (process.env.NODE_ENV === 'development') {
          logger.warn(`Anomalous access pattern detected: User ${userId}, IP ${clientIP}`, {
            confidence: anomalyResult.confidence,
            riskScore: anomalyResult.riskScore,
            reasons: anomalyResult.reasons,
          })
        }

        // 高リスクの場合はアクセスを制限
        if (anomalyResult.riskScore > 80) {
          // DDoS保護システムと統合
          await ddosProtection.updateIpReputation(clientIP, false, {
            userAgent: req.get('User-Agent'),
            endpoint: req.path,
          })

          return res.status(429).json({
            error: 'Suspicious activity detected',
            message: 'Your access pattern appears unusual. Please verify your identity.',
            code: 'ANOMALOUS_PATTERN',
            recommendations: anomalyResult.recommendations,
            retryAfter: 300, // 5分後に再試行
          })
        }

        // 中リスクの場合は警告のみ
        res.setHeader('X-Security-Warning', 'Unusual access pattern detected')
        res.setHeader('X-Security-Recommendations', anomalyResult.recommendations.join(', '))
      }

      next()
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Anomaly detection middleware error:', error)
      }
      next()
    }
  }
}

/**
 * GeoIP統合DDoS保護ミドルウェア
 */
export function geoEnhancedDDoSMiddleware() {
  return async (req: Request, res: Response, next: NextFunction) => {
    try {
      const clientIP = getClientIP(req)
      const userAgent = req.get('User-Agent')
      const userId = (req as any).user?.id

      // 地理情報を考慮したDDoS保護
      const geoLocation = req.geoLocation
      if (geoLocation) {
        // 高脅威地域からのアクセスは厳しく制限
        let baseLimit = 100 // 基本制限（1分間）

        if (geoLocation.threat > 70) baseLimit = 20
        else if (geoLocation.threat > 50) baseLimit = 50
        else if (geoLocation.proxy || geoLocation.vpn) baseLimit = 30
        else if (geoLocation.hosting) baseLimit = 40

        // カスタム制限設定でDDoS保護をチェック
        const protection = await ddosProtection.checkProtection(clientIP, userAgent, userId)

        if (!protection.allowed) {
          // IP reputationを更新
          await ddosProtection.updateIpReputation(clientIP, false, {
            userAgent,
            endpoint: req.path,
          })

          return res.status(429).json({
            error: 'Rate limit exceeded',
            message: 'Too many requests. Please try again later.',
            code: 'RATE_LIMITED',
            retryAfter: protection.blockDuration,
            geoEnhanced: true,
            reason: protection.reason,
          })
        }

        // 成功時のIP reputation更新
        await ddosProtection.updateIpReputation(clientIP, true, {
          userAgent,
          endpoint: req.path,
        })
      }

      next()
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Geo-enhanced DDoS middleware error:', error)
      }
      next()
    }
  }
}

/**
 * 国別アクセス制限（特定エンドポイント用）
 */
export function countryAccessMiddleware(allowedCountries: string[]) {
  return (req: Request, res: Response, next: NextFunction) => {
    const geoLocation = req.geoLocation

    if (!geoLocation) {
      // 地理情報がない場合は拒否
      return res.status(403).json({
        error: 'Access denied',
        message: 'Geographic verification required',
        code: 'GEO_VERIFICATION_REQUIRED',
      })
    }

    if (!allowedCountries.includes(geoLocation.countryCode)) {
      if (process.env.NODE_ENV === 'development') {
        logger.warn(`Country access denied: ${geoLocation.countryCode} not in allowed list`)
      }

      return res.status(403).json({
        error: 'Access denied',
        message: `Access from ${geoLocation.country} is not permitted`,
        code: 'COUNTRY_RESTRICTED',
      })
    }

    next()
  }
}

/**
 * VPN/Proxy検知ミドルウェア
 */
export function proxyDetectionMiddleware(blockProxies = true, blockVPN = false) {
  return (req: Request, res: Response, next: NextFunction) => {
    const geoLocation = req.geoLocation

    if (geoLocation) {
      if (blockProxies && geoLocation.proxy) {
        if (process.env.NODE_ENV === 'development') {
          logger.warn(`Proxy access blocked: ${geoLocation.ip}`)
        }
        return res.status(403).json({
          error: 'Proxy access denied',
          message: 'Access through proxy servers is not allowed',
          code: 'PROXY_BLOCKED',
        })
      }

      if (blockVPN && geoLocation.vpn) {
        if (process.env.NODE_ENV === 'development') {
          logger.warn(`VPN access blocked: ${geoLocation.ip}`)
        }
        return res.status(403).json({
          error: 'VPN access denied',
          message: 'Access through VPN is not allowed',
          code: 'VPN_BLOCKED',
        })
      }

      if (geoLocation.tor) {
        if (process.env.NODE_ENV === 'development') {
          logger.warn(`Tor access blocked: ${geoLocation.ip}`)
        }
        return res.status(403).json({
          error: 'Tor access denied',
          message: 'Access through Tor network is not allowed',
          code: 'TOR_BLOCKED',
        })
      }
    }

    next()
  }
}

/**
 * GeoIPステータス情報ミドルウェア（管理者用）
 */
export function geoStatusMiddleware() {
  return async (req: Request, res: Response, _next: NextFunction) => {
    try {
      // 管理者権限チェック（実装は認証システムによる）
      const isAdmin = (req as any).user?.role === 'admin'
      if (!isAdmin) {
        return res.status(403).json({ error: 'Admin access required' })
      }

      const stats = await geoIPService.getGeoStats()

      res.json({
        geoStats: stats,
        timestamp: new Date().toISOString(),
      })
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Geo status middleware error:', error)
      }
      res.status(500).json({ error: 'Failed to retrieve geo statistics' })
    }
  }
}

/**
 * クライアントIP取得（プロキシ対応）
 */
function getClientIP(req: Request): string {
  // X-Forwarded-For ヘッダーから取得（プロキシ経由の場合）
  const xForwardedFor = req.get('X-Forwarded-For')
  if (xForwardedFor) {
    // 複数のIPが含まれている場合は最初の値を使用
    return xForwardedFor.split(',')[0].trim()
  }

  // X-Real-IP ヘッダーから取得（nginx等）
  const xRealIP = req.get('X-Real-IP')
  if (xRealIP) {
    return xRealIP.trim()
  }

  // CF-Connecting-IP ヘッダーから取得（Cloudflare）
  const cfConnectingIP = req.get('CF-Connecting-IP')
  if (cfConnectingIP) {
    return cfConnectingIP.trim()
  }

  // 直接接続の場合
  return req.ip || req.connection.remoteAddress || '127.0.0.1'
}

export default {
  geoLocationMiddleware,
  geoRestrictionMiddleware,
  anomalyDetectionMiddleware,
  geoEnhancedDDoSMiddleware,
  countryAccessMiddleware,
  proxyDetectionMiddleware,
  geoStatusMiddleware,
}

/**
 * Next.js API Routes用 Rate Limiting ミドルウェア
 * Developer 3: API Rate Limiting・DDoS防止・Redis実装
 */

import { NextRequest, NextResponse } from 'next/server'
import { logger } from '../../services/logger'
import {
  slidingWindowLimiter,
  ddosProtection,
  type RateLimitConfig,
} from '@/lib/security/rateLimiting'
// import { z } from 'zod' // TODO: Will be used in future

// レート制限設定の種類
export enum RateLimitType {
  STRICT = 'strict', // 厳格（ログイン、パスワードリセットなど）
  NORMAL = 'normal', // 通常のAPI
  LENIENT = 'lenient', // 緩い（静的リソース、読み取り専用など）
  PREMIUM = 'premium', // プレミアムユーザー用
  ADMIN = 'admin', // 管理者用
}

// 事前定義されたレート制限設定
const RATE_LIMIT_CONFIGS: Record<RateLimitType, RateLimitConfig[]> = {
  [RateLimitType.STRICT]: [
    { windowMs: 15 * 60 * 1000, maxRequests: 5 }, // 15分間に5回
    { windowMs: 60 * 60 * 1000, maxRequests: 10 }, // 1時間に10回
  ],
  [RateLimitType.NORMAL]: [
    { windowMs: 60 * 1000, maxRequests: 100 }, // 1分間に100回
    { windowMs: 15 * 60 * 1000, maxRequests: 1000 }, // 15分間に1000回
  ],
  [RateLimitType.LENIENT]: [
    { windowMs: 60 * 1000, maxRequests: 300 }, // 1分間に300回
    { windowMs: 15 * 60 * 1000, maxRequests: 5000 }, // 15分間に5000回
  ],
  [RateLimitType.PREMIUM]: [
    { windowMs: 60 * 1000, maxRequests: 500 }, // 1分間に500回
    { windowMs: 15 * 60 * 1000, maxRequests: 10000 }, // 15分間に10000回
  ],
  [RateLimitType.ADMIN]: [
    { windowMs: 60 * 1000, maxRequests: 1000 }, // 1分間に1000回
    { windowMs: 15 * 60 * 1000, maxRequests: 20000 }, // 15分間に20000回
  ],
}

// Rate Limit オプション
export interface RateLimitOptions {
  type: RateLimitType
  customConfig?: RateLimitConfig[]
  keyGenerator?: (req: NextRequest) => string
  skipIf?: (req: NextRequest) => Promise<boolean>
  onLimitReached?: (req: NextRequest, identifier: string) => void
  enableDDoSProtection?: boolean
  whitelist?: string[] // 除外するIP一覧
}

// クライアント識別子生成
const defaultKeyGenerator = (req: NextRequest): string => {
  const forwarded = req.headers.get('x-forwarded-for')
  const realIp = req.headers.get('x-real-ip')
  const remoteAddr = forwarded?.split(',')[0] || realIp || req.ip || 'unknown'

  // 認証ユーザーの場合はユーザーIDも含める
  const userId = req.headers.get('x-user-id')
  if (userId) {
    return `${remoteAddr}:${userId}`
  }

  return remoteAddr
}

// User-Agent解析
const _parseUserAgent = ( // TODO: Will be used in future
  userAgent: string | null
): {
  isMobile: boolean
  isBot: boolean
  browser: string
  os: string
} => {
  if (!userAgent) {
    return { isMobile: false, isBot: true, browser: 'unknown', os: 'unknown' }
  }

  const ua = userAgent.toLowerCase()

  return {
    isMobile: /mobile|android|iphone|ipad/.test(ua),
    isBot: /bot|crawler|spider|scraper|curl|wget/.test(ua),
    browser: ua.includes('chrome')
      ? 'chrome'
      : ua.includes('firefox')
        ? 'firefox'
        : ua.includes('safari')
          ? 'safari'
          : 'other',
    os: ua.includes('windows')
      ? 'windows'
      : ua.includes('mac')
        ? 'mac'
        : ua.includes('linux')
          ? 'linux'
          : ua.includes('android')
            ? 'android'
            : ua.includes('ios')
              ? 'ios'
              : 'other',
  }
}

/**
 * Rate Limiting ミドルウェア関数
 */
export function withRateLimit(options: RateLimitOptions) {
  return async function rateLimitMiddleware(
    request: NextRequest,
    handler: (req: NextRequest) => Promise<NextResponse>
  ): Promise<NextResponse> {
    try {
      const identifier = options.keyGenerator?.(request) || defaultKeyGenerator(request)
      const userAgent = request.headers.get('user-agent')
      const userId = request.headers.get('x-user-id')

      // スキップ条件チェック
      if (options.skipIf && (await options.skipIf(request))) {
        return handler(request)
      }

      // ホワイトリストチェック
      if (options.whitelist) {
        const clientIp = identifier.split(':')[0]
        if (options.whitelist.includes(clientIp)) {
          return handler(request)
        }
      }

      // DDoS保護チェック
      if (options.enableDDoSProtection) {
        const ddosResult = await ddosProtection.checkProtection(
          identifier.split(':')[0], // IP部分のみ
          userAgent || undefined,
          userId || undefined
        )

        if (!ddosResult.allowed) {
          return NextResponse.json(
            {
              error: 'Request Blocked',
              message: ddosResult.reason,
              recommendations: ddosResult.recommendations,
              retryAfter: ddosResult.blockDuration,
            },
            {
              status: 429,
              headers: {
                'Retry-After': ddosResult.blockDuration?.toString() || '60',
                'X-RateLimit-Blocked-Reason': ddosResult.reason || 'DDoS Protection',
              },
            }
          )
        }
      }

      // 設定されたレート制限をチェック
      const configs = options.customConfig || RATE_LIMIT_CONFIGS[options.type]
      const results = await slidingWindowLimiter.checkMultipleLimit(
        identifier,
        configs.map((config, index) => ({ name: `limit_${index}`, config }))
      )

      // いずれかの制限に引っかかった場合
      const failedLimit = Object.values(results).find((result) => !result.success)

      if (failedLimit) {
        // リミット到達時のコールバック
        options.onLimitReached?.(request, identifier)

        // IP reputation更新（失敗として記録）
        if (options.enableDDoSProtection) {
          await ddosProtection.updateIpReputation(identifier.split(':')[0], false, {
            userAgent: userAgent || undefined,
            endpoint: request.nextUrl.pathname,
          })
        }

        return NextResponse.json(
          {
            error: 'Too Many Requests',
            message: 'レート制限に達しました。しばらくお待ちください。',
            limit: failedLimit.limit,
            remaining: failedLimit.remaining,
            resetTime: failedLimit.resetTime,
            retryAfter: failedLimit.retryAfter,
          },
          {
            status: 429,
            headers: {
              'X-RateLimit-Limit': failedLimit.limit.toString(),
              'X-RateLimit-Remaining': failedLimit.remaining.toString(),
              'X-RateLimit-Reset': failedLimit.resetTime.getTime().toString(),
              'Retry-After': failedLimit.retryAfter?.toString() || '60',
            },
          }
        )
      }

      // リクエスト成功
      const response = await handler(request)

      // IP reputation更新（成功として記録）
      if (options.enableDDoSProtection && response.status < 400) {
        await ddosProtection.updateIpReputation(identifier.split(':')[0], true, {
          userAgent: userAgent || undefined,
          endpoint: request.nextUrl.pathname,
        })
      }

      // レート制限情報をレスポンスヘッダーに追加
      const primaryResult = results.limit_0 // 最初の制限を主要な制限として使用
      if (primaryResult) {
        response.headers.set('X-RateLimit-Limit', primaryResult.limit.toString())
        response.headers.set('X-RateLimit-Remaining', primaryResult.remaining.toString())
        response.headers.set('X-RateLimit-Reset', primaryResult.resetTime.getTime().toString())
      }

      return response
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Rate limiting middleware error:', error)
      }
      // エラー時はリクエストを通す
      return handler(request)
    }
  }
}

/**
 * 特定のエンドポイント向けの事前設定されたミドルウェア
