      expect(next).toHaveBeenCalledOnce()
    })

    it('should validate CSRF tokens for unsafe HTTP methods', async () => {
      const middleware = csrf.middleware()
      const req = {
        method: 'POST',
        path: '/test',
        headers: {},
        ip: '127.0.0.1',
        get: vi.fn().mockReturnValue('test-agent'),
