      const { getRedisClient } = await import('../rateLimiting')
      vi.mocked(getRedisClient).mockRejectedValueOnce(new Error('Redis connection failed'))

      const keyManagerWithFailedRedis = new KeyManagementSystem(masterKey)
      const key = await keyManagerWithFailedRedis.generateEncryptionKey()

      expect(key).toBeTruthy()
      expect(key.status).toBe('active')

      keyManagerWithFailedRedis.destroy()
    })

    it('should handle key generation errors', async () => {
      // crypto.randomUUID のモックでエラーを発生させる
      vi.spyOn(crypto, 'randomUUID').mockImplementationOnce(() => {
        throw new Error('UUID generation failed')
      })

      await expect(keyManager.generateEncryptionKey()).rejects.toThrow()
    })

    it('should handle rotation errors gracefully', async () => {
      // キーの取得でエラーを発生させる
      vi.spyOn(keyManager as any, 'getActiveKeys').mockRejectedValueOnce(
        new Error('Key fetch failed')
      )

      await expect(keyManager.performKeyRotation()).rejects.toThrow('Key fetch failed')
    })
  })

  describe('セキュリティ機能', () => {
    it('should log security events for key revocation', async () => {
      const key = await keyManager.generateEncryptionKey()
      const logSpy = vi.spyOn(keyManager as any, 'logSecurityEvent')

      await keyManager.revokeKey(key.id, 'test revocation')

      expect(logSpy).toHaveBeenCalledWith(
        'KEY_REVOKED',
        expect.objectContaining({
          keyId: key.id,
          reason: 'test revocation',
        })
      )
    })

    it('should prevent access to revoked keys for decryption', async () => {
      const encryptionService = new EnhancedEncryptionService(masterKey)

      const { encrypted, iv, tag, metadata } = await encryptionService.encrypt('test data')

      await keyManager.revokeKey(metadata.keyId)

      await expect(encryptionService.decrypt(encrypted, iv, tag, metadata)).rejects.toThrow(
        'Cannot decrypt with revoked key'
      )

      encryptionService.destroy()
    })

    it('should use proper key derivation parameters', async () => {
      const key = await keyManager.generateEncryptionKey()

      expect(key.derivedFrom).toBeTruthy()
      expect(key.derivedFrom!.length).toBe(64) // 32 bytes as hex = 64 chars
    })
  })

  describe('パフォーマンス', () => {
    it('should handle concurrent key operations', async () => {
      const promises = Array.from({ length: 10 }, () => keyManager.generateEncryptionKey())

      const keys = await Promise.all(promises)
      const keyIds = keys.map((k) => k.id)
      const uniqueIds = new Set(keyIds)

      expect(uniqueIds.size).toBe(10) // All keys should be unique
    })

    it('should cache keys for performance', async () => {
      const key = await keyManager.generateEncryptionKey()

      const startTime = Date.now()
      await keyManager.getKeyById(key.id) // First call (from Redis/storage)
      const firstCallTime = Date.now() - startTime

      const startTime2 = Date.now()
      await keyManager.getKeyById(key.id) // Second call (from cache)
      const secondCallTime = Date.now() - startTime2

      // 2回目のコールはキャッシュから取得されるので高速のはず
      expect(secondCallTime).toBeLessThanOrEqual(firstCallTime)
    })

    it('should limit maximum active keys', async () => {
      // 制限を超える数のキーを生成
      for (let i = 0; i < 5; i++) {
        await keyManager.generateEncryptionKey()
      }

      const stats = await keyManager.getKeyUsageStatistics()
      expect(stats.activeKeys).toBeLessThanOrEqual(3) // maxActiveKeys = 3
    })
  })
})

describe('EnhancedEncryptionService', () => {
  let encryptionService: EnhancedEncryptionService
  let masterKey: string

  beforeEach(() => {
    masterKey = crypto.randomBytes(32).toString('hex')
    encryptionService = new EnhancedEncryptionService(masterKey, {
      autoRotationEnabled: false,
    })
  })

  afterEach(() => {
    encryptionService.destroy()
  })

  describe('暗号化・復号化', () => {
    it('should encrypt and decrypt data successfully', async () => {
      const originalData = 'sensitive information'

      const encrypted = await encryptionService.encrypt(originalData)
      const decrypted = await encryptionService.decrypt(
        encrypted.encrypted,
        encrypted.iv,
        encrypted.tag,
        encrypted.metadata
      )

      expect(decrypted).toBe(originalData)
    })

    it('should include metadata in encryption result', async () => {
      const result = await encryptionService.encrypt('test data')

      expect(result.metadata).toBeTruthy()
      expect(result.metadata.keyId).toBeTruthy()
      expect(result.metadata.algorithm).toBe('aes-256-gcm')
      expect(result.metadata.timestamp).toBeCloseTo(Date.now(), -2)
    })

    it('should handle different data types', async () => {
      const testCases = [
        'simple string',
        JSON.stringify({ complex: 'object', with: ['array', 'values'] }),
        'special characters: áéíóú ñ ¿¡',
        'numbers and symbols: 123 !@#$%^&*()',
        '',
      ]

      for (const testData of testCases) {
        const encrypted = await encryptionService.encrypt(testData)
        const decrypted = await encryptionService.decrypt(
          encrypted.encrypted,
          encrypted.iv,
          encrypted.tag,
          encrypted.metadata
        )

        expect(decrypted).toBe(testData)
      }
    })

    it('should fail decryption with wrong key', async () => {
      const encrypted = await encryptionService.encrypt('test data')

      // 異なるキーIDでメタデータを改ざん
      const tamperedMetadata = {
        ...encrypted.metadata,
        keyId: crypto.randomUUID(),
      }

      await expect(
        encryptionService.decrypt(
          encrypted.encrypted,
          encrypted.iv,
          encrypted.tag,
          tamperedMetadata
        )
      ).rejects.toThrow('Decryption key not found')
    })

    it('should fail decryption with corrupted data', async () => {
      const encrypted = await encryptionService.encrypt('test data')

      // 暗号化データを改ざん
      const tamperedData = encrypted.encrypted.substring(0, -4) + 'xxxx'

      await expect(
        encryptionService.decrypt(tamperedData, encrypted.iv, encrypted.tag, encrypted.metadata)
      ).rejects.toThrow('Decryption failed')
    })

    // Property-based testing
    it('should handle arbitrary input data', () => {
      fc.assert(
        fc.asyncProperty(fc.string({ minLength: 0, maxLength: 1000 }), async (data) => {
          const encrypted = await encryptionService.encrypt(data)
          const decrypted = await encryptionService.decrypt(
            encrypted.encrypted,
            encrypted.iv,
            encrypted.tag,
            encrypted.metadata
          )
          expect(decrypted).toBe(data)
        })
      )
    })
  })

  describe('キー管理統合', () => {
    it('should use key manager for encryption', async () => {
      const keyManager = encryptionService.getKeyManager()
      const getActiveKeySpy = vi.spyOn(keyManager, 'getActiveEncryptionKey')

      await encryptionService.encrypt('test data')

      expect(getActiveKeySpy).toHaveBeenCalled()
    })

    it('should support key rotation during operation', async () => {
      const data = 'test data'

      // データを暗号化
      const encrypted1 = await encryptionService.encrypt(data)

      // キーローテーション実行
      const keyManager = encryptionService.getKeyManager()
      await keyManager.performKeyRotation()

      // 新しいキーでデータを暗号化
      const encrypted2 = await encryptionService.encrypt(data)

      // 両方のデータが復号できる
      const decrypted1 = await encryptionService.decrypt(
        encrypted1.encrypted,
        encrypted1.iv,
        encrypted1.tag,
        encrypted1.metadata
      )
      const decrypted2 = await encryptionService.decrypt(
        encrypted2.encrypted,
        encrypted2.iv,
        encrypted2.tag,
        encrypted2.metadata
      )

      expect(decrypted1).toBe(data)
      expect(decrypted2).toBe(data)
      expect(encrypted1.metadata.keyId).not.toBe(encrypted2.metadata.keyId)
    })
  })

  describe('エラーハンドリング', () => {
    it('should handle key manager errors gracefully', async () => {
      const keyManager = encryptionService.getKeyManager()
      vi.spyOn(keyManager, 'getActiveEncryptionKey').mockRejectedValueOnce(
        new Error('Key manager error')
      )

      await expect(encryptionService.encrypt('test')).rejects.toThrow('Encryption failed')
    })

    it('should provide meaningful error messages', async () => {
      const keyManager = encryptionService.getKeyManager()
      const testKeyId = crypto.randomUUID()

      vi.spyOn(keyManager, 'getKeyById').mockResolvedValueOnce(null)

      const fakeMetadata = {
        keyId: testKeyId,
        keyVersion: 1,
        algorithm: 'aes-256-gcm',
        timestamp: Date.now(),
        rotationGeneration: 1,
      }

      await expect(
        encryptionService.decrypt('encrypted', 'iv', 'tag', fakeMetadata)
      ).rejects.toThrow(`Decryption key not found: ${testKeyId}`)
    })
  })
})

import { ValidationService } from './validation'
import { randomBytes, createHmac, timingSafeEqual } from 'crypto'
import Redis from 'ioredis'
import { getRedisClient } from './rateLimiting'
import { logger } from '../../services/logger'

export interface CSRFToken {
  token: string
  expiresAt: number
  userId?: string
  sessionId?: string
  fingerprint?: string
  nonce?: string
}

export interface CSRFConfig {
  tokenExpiry: number // milliseconds
  cookieName: string
  headerName: string
  secretKey: string
  doubleSubmitCookie: boolean
  sameSite: 'strict' | 'lax' | 'none'
  secure: boolean
  rotationInterval: number
  maxTokensPerUser: number
}

export interface CSRFValidationResult {
  valid: boolean
  error?: string
  riskScore?: number
  recommendations?: string[]
}

export class CSRFProtection {
  private config: CSRFConfig
  private tokenStore: Map<string, CSRFToken> = new Map()
  private redis: Redis | null = null
  private readonly DEFAULT_EXPIRY = 3600000 // 1 hour
  private rotationTimer: NodeJS.Timeout | null = null

  constructor(config: Partial<CSRFConfig> = {}) {
    this.config = {
      tokenExpiry: config.tokenExpiry || this.DEFAULT_EXPIRY,
      cookieName: config.cookieName || 'csrf-token',
      headerName: config.headerName || 'X-CSRF-Token',
      secretKey: config.secretKey || this.generateSecretKey(),
      doubleSubmitCookie: config.doubleSubmitCookie ?? true,
      sameSite: config.sameSite || 'strict',
      secure: config.secure ?? process.env.NODE_ENV === 'production',
      rotationInterval: config.rotationInterval || 3600000, // 1時間
      maxTokensPerUser: config.maxTokensPerUser || 5,
    }

    this.initializeRedis()
    this.startTokenRotation()
  }

  private async initializeRedis(): Promise<void> {
    try {
      this.redis = await getRedisClient()
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.warn('CSRF: Redis not available, using in-memory storage:', error)
      }
    }
  }

  /**
   * Generate a new CSRF token with enhanced security
   */
  async generateToken(userId?: string, sessionId?: string, fingerprint?: string): Promise<string> {
    try {
      // ユーザーのトークン数制限チェック
      if (userId) {
        await this.enforceTokenLimit(userId)
      }

      // 暗号学的に安全なランダムトークン生成
      const nonce = randomBytes(16).toString('hex')
      const timestamp = Date.now().toString()
      const context = [userId, sessionId, fingerprint, timestamp].filter(Boolean).join('|')

      // HMAC署名付きトークン
      const hmac = createHmac('sha256', this.config.secretKey)
      hmac.update(nonce + context)
      const signature = hmac.digest('hex')

      const tokenValue = `${nonce}.${timestamp}.${signature}`
      const expiresAt = Date.now() + this.config.tokenExpiry

      const token: CSRFToken = {
        token: tokenValue,
        expiresAt,
        userId,
        sessionId,
        fingerprint,
        nonce,
      }

      // Redis または メモリに保存
      await this.storeToken(tokenValue, token)

      return tokenValue
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('CSRF token generation error:', error)
      }
      throw new Error('Failed to generate CSRF token')
    }
  }

  /**
   * Enhanced CSRF token validation with integrity checking
   */
  async validateToken(
    tokenValue: string,
    userId?: string,
    sessionId?: string,
    fingerprint?: string
  ): Promise<CSRFValidationResult> {
    const result: CSRFValidationResult = {
      valid: false,
      riskScore: 0,
      recommendations: [],
    }

    try {
      if (!tokenValue || typeof tokenValue !== 'string') {
        result.error = 'Missing or invalid token format'
        result.riskScore = 100
        return result
      }

      // トークン構造の検証
      const parts = tokenValue.split('.')
      if (parts.length !== 3) {
        result.error = 'Malformed token structure'
        result.riskScore = 90
        result.recommendations.push('Token tampering detected')
        return result
      }

      const [nonce, timestamp, providedSignature] = parts

      // タイムスタンプ検証
      const tokenTimestamp = parseInt(timestamp)
      const now = Date.now()
      const age = now - tokenTimestamp

      if (age > this.config.tokenExpiry) {
        result.error = 'Token expired'
        result.riskScore = 30
        result.recommendations.push('Request new token')
        // 期限切れトークンを削除
        await this.removeToken(tokenValue)
        return result
      }

      // 異常に古い/新しいタイムスタンプの検知
      if (age < -5000 || age > this.config.tokenExpiry) {
        // 5秒の許容範囲
        result.error = 'Invalid token timestamp'
        result.riskScore = 80
        result.recommendations.push('Potential replay attack')
        return result
      }

      // ストレージからトークン取得
      const storedToken = await this.getToken(tokenValue)
      if (!storedToken) {
        result.error = 'Token not found or invalidated'
        result.riskScore = 70
        result.recommendations.push('Token may have been used or invalidated')
        return result
      }

      // HMAC署名検証
      const context = [userId, sessionId, fingerprint, timestamp].filter(Boolean).join('|')
      const hmac = createHmac('sha256', this.config.secretKey)
      hmac.update(nonce + context)
      const expectedSignature = hmac.digest('hex')

      // タイミング攻撃耐性のある比較
      if (
        providedSignature.length !== expectedSignature.length ||
        !timingSafeEqual(
          Buffer.from(providedSignature, 'hex'),
          Buffer.from(expectedSignature, 'hex')
        )
      ) {
        result.error = 'Invalid token signature'
        result.riskScore = 95
        result.recommendations.push('Token integrity compromised')
        return result
      }

      // コンテキスト検証
      if (userId && storedToken.userId && storedToken.userId !== userId) {
        result.error = 'User context mismatch'
        result.riskScore = 85
        result.recommendations.push('Potential session hijacking')
        return result
      }

      if (sessionId && storedToken.sessionId && storedToken.sessionId !== sessionId) {
        result.error = 'Session context mismatch'
        result.riskScore = 85
        result.recommendations.push('Session mismatch detected')
        return result
      }

      // フィンガープリント検証（任意）
      if (fingerprint && storedToken.fingerprint && storedToken.fingerprint !== fingerprint) {
        result.riskScore = 40 // 警告レベル
        result.recommendations.push('Device fingerprint changed')
      }

      // 使い捨てトークンとして削除（オプション）
      if (process.env.CSRF_ONE_TIME_USE === 'true') {
        await this.removeToken(tokenValue)
      }

      result.valid = true
      return result
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('CSRF token validation error:', error)
      }
      result.error = 'Validation system error'
      result.riskScore = 60
      result.recommendations.push('System error during validation')
      return result
    }
  }

  /**
   * Invalidate a token
   */
  async invalidateToken(tokenValue: string): Promise<void> {
    await this.removeToken(tokenValue)
  }

  /**
   * Redis/Memory token storage
   */
  private async storeToken(tokenValue: string, token: CSRFToken): Promise<void> {
    if (this.redis) {
      const key = `csrf:${tokenValue}`
      await this.redis.setex(key, Math.ceil(this.config.tokenExpiry / 1000), JSON.stringify(token))
    } else {
      this.tokenStore.set(tokenValue, token)
      this.cleanupExpiredTokens()
    }
  }

  /**
   * Get token from storage
   */
  private async getToken(tokenValue: string): Promise<CSRFToken | null> {
    if (this.redis) {
      const key = `csrf:${tokenValue}`
      const stored = await this.redis.get(key)
      return stored ? JSON.parse(stored) : null
    } else {
      return this.tokenStore.get(tokenValue) || null
    }
  }

  /**
   * Remove token from storage
   */
  private async removeToken(tokenValue: string): Promise<void> {
    if (this.redis) {
      const key = `csrf:${tokenValue}`
      await this.redis.del(key)
    } else {
      this.tokenStore.delete(tokenValue)
    }
  }

  /**
   * Enforce token limit per user
   */
  private async enforceTokenLimit(userId: string): Promise<void> {
    if (this.redis) {
      const userTokensKey = `csrf:user:${userId}`
      const tokenCount = await this.redis.zcard(userTokensKey)

      if (tokenCount >= this.config.maxTokensPerUser) {
        // 最も古いトークンを削除
        const oldestTokens = await this.redis.zrange(userTokensKey, 0, 0, 'WITHSCORES')
        if (oldestTokens.length > 0) {
          const oldestToken = oldestTokens[0]
          await this.removeToken(oldestToken)
          await this.redis.zrem(userTokensKey, oldestToken)
        }
      }
    }
  }

  /**
   * Track user tokens
   */
  private async trackUserToken(userId: string, tokenValue: string): Promise<void> {
    if (this.redis && userId) {
      const userTokensKey = `csrf:user:${userId}`
      const now = Date.now()
      await this.redis.zadd(userTokensKey, now, tokenValue)
      await this.redis.expire(userTokensKey, Math.ceil(this.config.tokenExpiry / 1000))
    }
  }

  /**
   * Enhanced Double Submit Cookie implementation
   */
  async setDoubleSubmitCookie(
    tokenValue: string,
    response?: unknown,
    options: {
      secure?: boolean
      sameSite?: 'strict' | 'lax' | 'none'
      domain?: string
      path?: string
    } = {}
  ): Promise<void> {
    const cookieOptions = {
      secure: options.secure ?? this.config.secure,
      sameSite: options.sameSite ?? this.config.sameSite,
      domain: options.domain,
      path: options.path ?? '/',
      maxAge: Math.floor(this.config.tokenExpiry / 1000),
      httpOnly: true,
    }

    if (this.config.doubleSubmitCookie) {
      // 筲名化されたトークンでDouble Submit Cookieを実装
      const hmac = createHmac('sha256', this.config.secretKey)
      hmac.update(tokenValue)
      const cookieToken = hmac.digest('hex').substring(0, 32)

      if (response) {
        // Server-side cookie setting
        response.cookie(this.config.cookieName, cookieToken, cookieOptions)
        // Additional cookie for CSRF double submit
        response.cookie(`${this.config.cookieName}-double`, tokenValue, {
          ...cookieOptions,
          httpOnly: false, // クライアントサイドでアクセス可能
        })
      } else if (typeof document !== 'undefined') {
        // Client-side cookie setting
        document.cookie = `${this.config.cookieName}=${cookieToken}; ${this.serializeCookieOptions(cookieOptions)}`
        document.cookie = `${this.config.cookieName}-double=${tokenValue}; ${this.serializeCookieOptions({ ...cookieOptions, httpOnly: false })}`
      }
    } else {
      // 通常のシングルクッキー
      if (response) {
        response.cookie(this.config.cookieName, tokenValue, cookieOptions)
      } else if (typeof document !== 'undefined') {
        document.cookie = `${this.config.cookieName}=${tokenValue}; ${this.serializeCookieOptions(cookieOptions)}`
      }
    }
  }

  /**
   * Serialize cookie options
   */
  private serializeCookieOptions(options: unknown): string {
    const parts: string[] = []

    Object.entries(options).forEach(([key, value]) => {
      if (value !== undefined && value !== null) {
        if (typeof value === 'boolean' && value) {
          parts.push(key)
        } else if (typeof value !== 'boolean') {
          parts.push(`${key}=${value}`)
        }
      }
    })

    return parts.join('; ')
  }

  /**
   * Get CSRF token from cookie (enhanced for double submit)
   */
  getTokenFromCookie(request?: unknown): { cookieToken?: string; headerToken?: string } | null {
    const getCookieValue = (name: string): string | null => {
      if (request && request.cookies) {
        // Server-side
        return request.cookies[name] || null
      } else if (typeof document !== 'undefined') {
        // Client-side
        const cookies = document.cookie.split(';')
        const cookie = cookies.find((c) => c.trim().startsWith(`${name}=`))
        return cookie ? cookie.split('=')[1].trim() : null
      }
      return null
    }

    if (this.config.doubleSubmitCookie) {
      return {
        cookieToken: getCookieValue(this.config.cookieName),
        headerToken: getCookieValue(`${this.config.cookieName}-double`),
      }
    } else {
      const token = getCookieValue(this.config.cookieName)
      return token ? { cookieToken: token } : null
    }
  }

  /**
   * Create CSRF-protected fetch wrapper
   */
  createProtectedFetch(): (input: RequestInfo | URL, init?: RequestInit) => Promise<Response> {
    return async (input: RequestInfo | URL, init: RequestInit = {}): Promise<Response> => {
      const method = init.method?.toUpperCase() || 'GET'

      // Only protect state-changing methods
      if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(method)) {
        // Get current token
        let token = this.getTokenFromCookie()

        // Generate new token if none exists
        if (!token) {
          token = this.generateToken()
          this.setTokenCookie(token)
        }

        // Add CSRF token to headers
        const headers = new Headers(init.headers)
        headers.set(this.config.headerName, token)

        init.headers = headers
      }

      return fetch(input, init)
    }
  }

  /**
   * Validate request for CSRF token
   */
  validateRequest(
    request: {
      method: string
      headers: { [key: string]: string }
      cookies?: { [key: string]: string }
    },
    userId?: string
  ): { valid: boolean; error?: string } {
    const method = request.method.toUpperCase()

    // Only validate state-changing methods
    if (!['POST', 'PUT', 'PATCH', 'DELETE'].includes(method)) {
      return { valid: true }
    }

    // Get token from header
    const tokenFromHeader =
      request.headers[this.config.headerName] ||
      request.headers[this.config.headerName.toLowerCase()]

    if (!tokenFromHeader) {
      return { valid: false, error: 'CSRF token missing from header' }
    }

    // Validate token
    const isValid = this.validateToken(tokenFromHeader, userId)

    if (!isValid) {
      return { valid: false, error: 'Invalid or expired CSRF token' }
    }

    return { valid: true }
  }

  /**
   * Enhanced middleware with comprehensive protection
   */
  middleware() {
    return async (req: unknown, res: unknown, next: unknown) => {
      try {
        // Enhanced CSRF token generation
        req.generateCSRFToken = async (userId?: string, sessionId?: string) => {
          const fingerprint = this.generateFingerprint(req)
          const token = await this.generateToken(userId, sessionId, fingerprint)

          await this.setDoubleSubmitCookie(token, res)

          if (userId) {
            await this.trackUserToken(userId, token)
          }

          return token
        }

        // CSRF token refresh endpoint
        if (req.path === '/api/csrf/refresh' && req.method === 'POST') {
          const newToken = await req.generateCSRFToken(req.user?.id, req.sessionID)
          return res.json({ token: newToken })
        }

        // Safe methods don't require CSRF protection
        if (['GET', 'HEAD', 'OPTIONS'].includes(req.method)) {
          return next()
        }

        // Enhanced CSRF validation for state-changing requests
        const fingerprint = this.generateFingerprint(req)
        const validation = await this.validateEnhancedRequest(
          req,
          req.user?.id,
          req.sessionID,
          fingerprint
        )

        if (!validation.valid) {
          if (process.env.NODE_ENV === 'development') {
            logger.warn('CSRF validation failed:', {
              ip: req.ip,
              userAgent: req.get('User-Agent'),
              userId: req.user?.id,
              error: validation.error,
              riskScore: validation.riskScore,
            })
          }

          return res.status(403).json({
            error: 'CSRF validation failed',
            message: validation.error,
            riskScore: validation.riskScore,
            recommendations: validation.recommendations,
            code: 'CSRF_VALIDATION_FAILED',
          })
        }

        // Log high-risk validations
        if (validation.riskScore && validation.riskScore > 40) {
          if (process.env.NODE_ENV === 'development') {
            logger.warn('High-risk CSRF validation:', {
              ip: req.ip,
              userId: req.user?.id,
              riskScore: validation.riskScore,
              recommendations: validation.recommendations,
            })
          }
        }

        next()
      } catch (error) {
        if (process.env.NODE_ENV === 'development') {
          logger.error('CSRF middleware error:', error)
        }
        return res.status(500).json({
          error: 'CSRF system error',
          message: 'Internal security system error',
          code: 'CSRF_SYSTEM_ERROR',
        })
      }
    }
  }

  /**
   * Enhanced request validation
   */
  private async validateEnhancedRequest(
    request: unknown,
    userId?: string,
    sessionId?: string,
    fingerprint?: string
  ): Promise<CSRFValidationResult> {
    const method = request.method.toUpperCase()

    // Skip validation for safe methods
    if (!['POST', 'PUT', 'PATCH', 'DELETE'].includes(method)) {
      return { valid: true }
    }

    let tokenFromHeader =
      request.headers[this.config.headerName] ||
      request.headers[this.config.headerName.toLowerCase()]

    if (this.config.doubleSubmitCookie) {
      // Double Submit Cookie validation
      const cookieTokens = this.getTokenFromCookie(request)

      if (!cookieTokens?.cookieToken || !cookieTokens?.headerToken) {
        return {
          valid: false,
          error: 'Missing double submit cookie tokens',
          riskScore: 80,
          recommendations: ['Double submit cookie validation required'],
        }
      }

      // Validate cookie token matches header token (after HMAC)
      const hmac = createHmac('sha256', this.config.secretKey)
      hmac.update(cookieTokens.headerToken)
      const expectedCookieToken = hmac.digest('hex').substring(0, 32)

      if (cookieTokens.cookieToken !== expectedCookieToken) {
        return {
          valid: false,
          error: 'Double submit cookie mismatch',
          riskScore: 95,
          recommendations: ['Potential CSRF attack detected'],
        }
      }

      tokenFromHeader = cookieTokens.headerToken
    }

    if (!tokenFromHeader) {
      return {
        valid: false,
        error: 'CSRF token missing from request',
        riskScore: 70,
        recommendations: ['Include CSRF token in request headers'],
      }
    }

    // Validate token integrity and context
    return await this.validateToken(tokenFromHeader, userId, sessionId, fingerprint)
  }

  /**
   * Generate device/request fingerprint
   */
  private generateFingerprint(request: unknown): string {
    const components = [
      request.get('User-Agent') || '',
      request.get('Accept-Language') || '',
      request.get('Accept-Encoding') || '',
      request.ip || '',
    ].join('|')

    const hmac = createHmac('sha256', this.config.secretKey)
    hmac.update(components)
    return hmac.digest('hex').substring(0, 16)
  }

  /**
   * Create form with CSRF token (for server-side rendering)
   */
  createFormWithToken(formHTML: string, userId?: string): string {
    const token = this.generateToken(userId)
    const hiddenInput = `<input type="hidden" name="csrf_token" value="${token}" />`

    // Insert hidden input after opening form tag
    return formHTML.replace(/(<form[^>]*>)/i, `$1\n${hiddenInput}`)
  }

  /**
   * Verify form submission token
   */
  verifyFormToken(formData: { [key: string]: unknown }, userId?: string): boolean {
    const token = formData.csrf_token || formData._token
    return this.validateToken(token, userId)
  }

  /**
   * Get token statistics
   */
  getTokenStats(): {
    totalTokens: number
    expiredTokens: number
    validTokens: number
  } {
    const now = Date.now()
    let expired = 0
    let valid = 0

    for (const token of this.tokenStore.values()) {
      if (now > token.expiresAt) {
        expired++
      } else {
        valid++
      }
    }

    return {
      totalTokens: this.tokenStore.size,
      expiredTokens: expired,
      validTokens: valid,
    }
  }

  /**
   * Clean up expired tokens
   */
  private cleanupExpiredTokens(): void {
    const now = Date.now()
    for (const [key, token] of this.tokenStore.entries()) {
      if (now > token.expiresAt) {
        this.tokenStore.delete(key)
      }
    }
  }

  /**
   * Generate secret key for token signing
   */
  private generateSecretKey(): string {
    return ValidationService.generateSecureToken(64)
  }

  /**
   * Clear all tokens (for testing)
   */
  clearAllTokens(): void {
    this.tokenStore.clear()
  }

  /**
   * Start token rotation and cleanup
   */
  private startTokenRotation(): void {
    // Cleanup expired tokens every 5 minutes
    setInterval(() => {
      this.cleanupExpiredTokens()
    }, 300000)

    // Token rotation for active sessions every hour
    if (this.config.rotationInterval > 0) {
      this.rotationTimer = setInterval(() => {
        this.rotateActiveTokens()
      }, this.config.rotationInterval)
    }
  }

  /**
   * Rotate active tokens for security
   */
  private async rotateActiveTokens(): Promise<void> {
    if (!this.redis) return

    try {
      // Get all active user token keys
      const userKeys = await this.redis.keys('csrf:user:*')

      for (const userKey of userKeys) {
        const userId = userKey.split(':')[2]
        const tokens = await this.redis.zrange(userKey, 0, -1)

        // Generate new tokens to replace old ones
        for (const oldToken of tokens) {
          const storedToken = await this.getToken(oldToken)
          if (storedToken && storedToken.expiresAt > Date.now()) {
            // Generate replacement token
            const newToken = await this.generateToken(
              storedToken.userId,
              storedToken.sessionId,
              storedToken.fingerprint
            )

            // Mark old token for gradual expiry (give clients time to update)
            const graceKey = `csrf:grace:${oldToken}`
            await this.redis.setex(graceKey, 300, newToken) // 5 minutes grace

            if (process.env.NODE_ENV === 'development') {
              logger.info(
            }
              `Token rotated for user ${userId}: ${oldToken.substring(0, 8)}... -> ${newToken.substring(0, 8)}...`
            )
          }
        }
      }
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Token rotation error:', error)
      }
    }
  }

  /**
   * Stop all timers
   */
  destroy(): void {
    if (this.rotationTimer) {
      clearInterval(this.rotationTimer)
      this.rotationTimer = null
    }
  }
}

// Global CSRF protection instance with environment configuration
export const csrfProtection = new CSRFProtection({
  tokenExpiry: parseInt(process.env.CSRF_TOKEN_EXPIRY || '3600000'), // 1 hour default
  cookieName: process.env.CSRF_COOKIE_NAME || 'csrf-token',
  headerName: process.env.CSRF_HEADER_NAME || 'X-CSRF-Token',
  secretKey:
    process.env.CSRF_SECRET ||
    (() => {
      if (process.env.NODE_ENV === 'production') {
        throw new Error('CSRF_SECRET must be set in production')
      }
      return 'development-secret-key-change-in-production-32-chars'
    })(),
  doubleSubmitCookie: process.env.CSRF_DOUBLE_SUBMIT !== 'false',
  sameSite: (process.env.CSRF_SAME_SITE as 'strict' | 'lax' | 'none') || 'strict',
  secure: process.env.CSRF_SECURE !== 'false',
  rotationInterval: parseInt(process.env.CSRF_ROTATION_INTERVAL || '3600000'),
  maxTokensPerUser: parseInt(process.env.CSRF_MAX_TOKENS_PER_USER || '5'),
})

// Enhanced React hook for CSRF token management
export function useCSRFToken(userId?: string): {
  token: string | null
  generateToken: () => Promise<string>
  validateToken: (token: string) => Promise<CSRFValidationResult>
  protectedFetch: typeof fetch
  refreshToken: () => Promise<string>
  clearToken: () => void
} {
  const generateToken = async (): Promise<string> => {
    const token = await csrfProtection.generateToken(userId)
    await csrfProtection.setDoubleSubmitCookie(token)
    return token
  }

  const validateToken = async (token: string): Promise<CSRFValidationResult> => {
    return await csrfProtection.validateToken(token, userId)
  }

  const refreshToken = async (): Promise<string> => {
    // Clear old token and generate new one
    const oldTokens = csrfProtection.getTokenFromCookie()
    if (oldTokens?.headerToken) {
      await csrfProtection.invalidateToken(oldTokens.headerToken)
    }

    return await generateToken()
  }

  const clearToken = (): void => {
    if (typeof document !== 'undefined') {
      document.cookie = `${csrfProtection.config.cookieName}=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;`
      if (csrfProtection.config.doubleSubmitCookie) {
        document.cookie = `${csrfProtection.config.cookieName}-double=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;`
      }
    }
  }

  const protectedFetch = async (
    input: RequestInfo | URL,
    init: RequestInit = {}
  ): Promise<Response> => {
    const method = init.method?.toUpperCase() || 'GET'

    if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(method)) {
      // Get or generate token
      const tokens = csrfProtection.getTokenFromCookie()
      let token: string

      if (csrfProtection.config.doubleSubmitCookie && tokens?.headerToken) {
        token = tokens.headerToken
      } else if (!csrfProtection.config.doubleSubmitCookie && tokens?.cookieToken) {
        token = tokens.cookieToken
      } else {
        token = await generateToken()
      }

      // Add CSRF token to headers
      const headers = new Headers(init.headers)
      headers.set(csrfProtection.config.headerName, token)
      init.headers = headers
    }

    return fetch(input, init)
  }

  const tokens = csrfProtection.getTokenFromCookie()
  const currentToken = csrfProtection.config.doubleSubmitCookie
    ? tokens?.headerToken
    : tokens?.cookieToken

  return {
    token: currentToken || null,
    generateToken,
    validateToken,
    protectedFetch,
    refreshToken,
    clearToken,
  }
}

export default CSRFProtection

/**
 * 自動キーローテーション・マルチバージョンキー管理システム
 * Developer 3: エンタープライズ級キー管理機能
 */

import crypto from 'crypto'
import Redis from 'ioredis'
import { getRedisClient } from './rateLimiting'
import type { KeyVersion, KeyRotationConfig, EncryptionMetadata } from './encryption'
import { logger } from '../../services/logger'

/**
 * キー管理システム
 */
export class KeyManagementSystem {
  private redis: Redis | null = null
  private masterKey: Buffer
  private config: KeyRotationConfig
  private rotationTimer: NodeJS.Timeout | null = null
  private keyUsageCounter: Map<string, number> = new Map()
  private keyCache: Map<string, KeyVersion> = new Map()

  constructor(masterKey: string, config?: Partial<KeyRotationConfig>) {
    this.masterKey = Buffer.from(masterKey, 'hex')
    this.config = {
      rotationInterval: config?.rotationInterval || 86400000, // 24時間
      keyRetentionPeriod: config?.keyRetentionPeriod || 7 * 86400000, // 7日間
      autoRotationEnabled: config?.autoRotationEnabled ?? true,
      masterKeyRotationThreshold: config?.masterKeyRotationThreshold || 10000,
      keyDerivationRounds: config?.keyDerivationRounds || 100000,
      maxActiveKeys: config?.maxActiveKeys || 5,
    }

    this.initializeRedis()
    this.startKeyRotationScheduler()
  }

  /**
   * Redis接続初期化
   */
  private async initializeRedis(): Promise<void> {
    try {
      this.redis = await getRedisClient()
      if (process.env.NODE_ENV === 'development') {
        logger.info('Key Management System: Redis connected')
      }
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.warn('Key Management System: Redis not available, using in-memory storage:', error)
      }
    }
  }

  /**
   * キーローテーションスケジューラーの開始
   */
  private startKeyRotationScheduler(): void {
    if (!this.config.autoRotationEnabled) {
      return
    }

    this.rotationTimer = setInterval(async () => {
      try {
        await this.performKeyRotation()
      } catch (error) {
        if (process.env.NODE_ENV === 'development') {
          logger.error('Scheduled key rotation failed:', error)
        }
      }
    }, this.config.rotationInterval)

    if (process.env.NODE_ENV === 'development') {
      logger.info(`Key rotation scheduler started (interval: ${this.config.rotationInterval}ms)`)
    }
  }

  /**
   * 新しい暗号化キーの生成
   */
  async generateEncryptionKey(purpose: KeyVersion['purpose'] = 'encryption'): Promise<KeyVersion> {
    const keyId = crypto.randomUUID()
    const salt = crypto.randomBytes(32)

    // PBKDF2でマスターキーから派生キーを生成
    const derivedKey = crypto.pbkdf2Sync(
      this.masterKey,
      salt,
      this.config.keyDerivationRounds,
      32, // 256-bit key
      'sha512'
    )

    const keyVersion: KeyVersion = {
      id: keyId,
      key: derivedKey,
      derivedFrom: salt.toString('hex'),
      createdAt: Date.now(),
      status: 'active',
      algorithm: 'aes-256-gcm',
      purpose,
      rotationSchedule: this.config.rotationInterval,
    }

    // キーをストレージに保存
    await this.storeKey(keyVersion)
    this.keyCache.set(keyId, keyVersion)

    if (process.env.NODE_ENV === 'development') {
      logger.info(`New encryption key generated: ${keyId.substring(0, 8)}... (${purpose})`)
    }
    return keyVersion
  }

  /**
   * アクティブな暗号化キーの取得
   */
  async getActiveEncryptionKey(): Promise<KeyVersion> {
    try {
      // キャッシュから最新のアクティブキーを取得
      let activeKey = Array.from(this.keyCache.values())
        .filter((key) => key.status === 'active' && key.purpose === 'encryption')
        .sort((a, b) => b.createdAt - a.createdAt)[0]

      if (!activeKey) {
        // Redisから最新のアクティブキーを検索
        activeKey = await this.findActiveKeyFromStorage('encryption')
      }

      if (!activeKey) {
        // アクティブキーが存在しない場合は新規生成
        if (process.env.NODE_ENV === 'development') {
          logger.warn('No active encryption key found, generating new key')
        }
        activeKey = await this.generateEncryptionKey()
      }

      // 使用回数をカウント
      const usage = this.keyUsageCounter.get(activeKey.id) || 0
      this.keyUsageCounter.set(activeKey.id, usage + 1)

      // 使用回数が閾値を超えた場合はローテーション
      if (usage >= this.config.masterKeyRotationThreshold) {
        if (process.env.NODE_ENV === 'development') {
          logger.info(`Key usage threshold exceeded for ${activeKey.id}, triggering rotation`)
        }
        await this.performKeyRotation()
        // 新しいアクティブキーを取得
        return await this.getActiveEncryptionKey()
      }

      return activeKey
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to get active encryption key:', error)
      }
      throw new Error('Encryption key retrieval failed')
    }
  }

  /**
   * 特定のキーIDでキーを取得
   */
  async getKeyById(keyId: string): Promise<KeyVersion | null> {
    try {
      // キャッシュから確認
      if (this.keyCache.has(keyId)) {
        return this.keyCache.get(keyId)!
      }

      // Redisから取得
      if (this.redis) {
        const keyData = await this.redis.get(`key:${keyId}`)
        if (keyData) {
          const keyVersion = this.deserializeKey(keyData)
          this.keyCache.set(keyId, keyVersion)
          return keyVersion
        }
      }

      if (process.env.NODE_ENV === 'development') {
        logger.warn(`Key not found: ${keyId}`)
      }
      return null
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error(`Failed to retrieve key ${keyId}:`, error)
      }
      return null
    }
  }

  /**
   * キーローテーション実行
   */
  async performKeyRotation(): Promise<void> {
    try {
      if (process.env.NODE_ENV === 'development') {
        logger.info('Starting key rotation process...')
      }

      // 現在のアクティブキーを取得
      const activeKeys = await this.getActiveKeys()

      // 新しいキーを生成
      const newKey = await this.generateEncryptionKey()

      // 古いキーを非推奨に変更
      for (const oldKey of activeKeys) {
        await this.deprecateKey(oldKey.id)
      }

      // 期限切れキーのクリーンアップ
      await this.cleanupExpiredKeys()

      if (process.env.NODE_ENV === 'development') {
        logger.info(`Key rotation completed. New key: ${newKey.id.substring(0, 8)}...`)
      }

      // ローテーション統計を更新
      await this.updateRotationStatistics()
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Key rotation failed:', error)
      }
      throw error
    }
  }

  /**
   * キーの非推奨化
   */
  async deprecateKey(keyId: string): Promise<void> {
    const key = await this.getKeyById(keyId)
    if (!key) {
      if (process.env.NODE_ENV === 'development') {
        logger.warn(`Cannot deprecate non-existent key: ${keyId}`)
      }
      return
    }

    key.status = 'deprecated'
    key.expiresAt = Date.now() + this.config.keyRetentionPeriod

    await this.storeKey(key)
    this.keyCache.set(keyId, key)

    if (process.env.NODE_ENV === 'development') {
      logger.info(
        `Key deprecated: ${keyId.substring(0, 8)}... (expires: ${new Date(key.expiresAt!)})`
      )
    }
  }

  /**
   * キーの取り消し
   */
  async revokeKey(keyId: string, reason?: string): Promise<void> {
    const key = await this.getKeyById(keyId)
    if (!key) {
      if (process.env.NODE_ENV === 'development') {
        logger.warn(`Cannot revoke non-existent key: ${keyId}`)
      }
      return
    }

    key.status = 'revoked'
    key.expiresAt = Date.now() // 即座に期限切れに

    await this.storeKey(key)
    this.keyCache.set(keyId, key)

    if (process.env.NODE_ENV === 'development') {
      logger.warn(`Key revoked: ${keyId.substring(0, 8)}... ${reason ? `(reason: ${reason})` : ''}`)
    }

    // セキュリティログ記録
    await this.logSecurityEvent('KEY_REVOKED', {
      keyId,
      reason,
      timestamp: Date.now(),
    })
  }

  /**
   * 段階的再暗号化の実行
   */
  async performGradualReEncryption(
    oldKeyId: string,
    newKeyId: string,
    batchSize: number = 100
  ): Promise<{
    processed: number
    failed: number
    completed: boolean
  }> {
    try {
      const oldKey = await this.getKeyById(oldKeyId)
      const newKey = await this.getKeyById(newKeyId)

      if (!oldKey || !newKey) {
        throw new Error('Required keys not found for re-encryption')
      }

      // 再暗号化が必要なデータのリストを取得
      const dataToReEncrypt = await this.getDataForReEncryption(oldKeyId, batchSize)

      let processed = 0
      let failed = 0

      for (const dataItem of dataToReEncrypt) {
        try {
          // 旧キーで復号
          const decryptedData = this.decryptWithKey(dataItem.encryptedData, oldKey)

          // 新キーで再暗号化
          const reEncryptedData = this.encryptWithKey(decryptedData, newKey)

          // データベース更新
          await this.updateEncryptedData(dataItem.id, reEncryptedData, newKeyId)

          processed++
        } catch (error) {
          if (process.env.NODE_ENV === 'development') {
            logger.error(`Re-encryption failed for data item ${dataItem.id}:`, error)
          }
          failed++
        }
      }

      const completed = dataToReEncrypt.length < batchSize // 最後のバッチの場合

      if (process.env.NODE_ENV === 'development') {
        logger.info(
          `Re-encryption batch completed: ${processed} processed, ${failed} failed, completed: ${completed}`
        )
      }

      return { processed, failed, completed }
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Gradual re-encryption failed:', error)
      }
      throw error
    }
  }

  /**
   * キー使用統計の取得
   */
  async getKeyUsageStatistics(): Promise<{
    activeKeys: number
    deprecatedKeys: number
    revokedKeys: number
    totalUsage: number
    rotationHistory: Array<{ timestamp: number; keyId: string; action: string }>
  }> {
    try {
      const allKeys = await this.getAllKeys()

      const stats = {
        activeKeys: allKeys.filter((k) => k.status === 'active').length,
        deprecatedKeys: allKeys.filter((k) => k.status === 'deprecated').length,
        revokedKeys: allKeys.filter((k) => k.status === 'revoked').length,
        totalUsage: Array.from(this.keyUsageCounter.values()).reduce(
          (sum, count) => sum + count,
          0
        ),
        rotationHistory: await this.getRotationHistory(),
      }

      return stats
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to get key usage statistics:', error)
      }
      throw error
    }
  }

  /**
   * 本番環境用キー管理戦略
   */
  async setupProductionKeyStrategy(): Promise<void> {
    if (process.env.NODE_ENV !== 'production') {
      logger.warn('Production key strategy setup called in non-production environment')
      return
    }

    try {
      // HSM統合の準備（将来実装）
      await this.prepareHSMIntegration()

      // 分散キー管理の設定
      await this.setupDistributedKeyManagement()

      // 暗号化キー監査ログの有効化
      await this.enableKeyAuditLogging()

      // 災害復旧用キーバックアップの設定
      await this.setupKeyBackupStrategy()

      if (process.env.NODE_ENV === 'development') {
        logger.info('Production key management strategy initialized')
      }
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to setup production key strategy:', error)
      }
      throw error
    }
  }

  /**
   * キーをストレージに保存
   */
  private async storeKey(keyVersion: KeyVersion): Promise<void> {
    const serializedKey = this.serializeKey(keyVersion)

    if (this.redis) {
      await this.redis.setex(
        `key:${keyVersion.id}`,
        Math.ceil(this.config.keyRetentionPeriod / 1000),
        serializedKey
      )

      // インデックス更新
      await this.redis.zadd('keys:by_created', keyVersion.createdAt, keyVersion.id)
    } else {
      // メモリ内ストレージ（開発環境用）
      this.keyCache.set(keyVersion.id, keyVersion)
    }
  }

  /**
   * アクティブキーの取得
   */
  private async getActiveKeys(): Promise<KeyVersion[]> {
    const allKeys = await this.getAllKeys()
    return allKeys.filter((key) => key.status === 'active')
  }

  /**
   * ストレージからアクティブキーを検索
   */
  private async findActiveKeyFromStorage(purpose: string): Promise<KeyVersion | null> {
    if (!this.redis) return null

    try {
      const keyIds = await this.redis.zrevrange('keys:by_created', 0, 10)

      for (const keyId of keyIds) {
        const keyData = await this.redis.get(`key:${keyId}`)
        if (keyData) {
          const key = this.deserializeKey(keyData)
          if (key.status === 'active' && key.purpose === purpose) {
            return key
          }
        }
      }

      return null
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to find active key from storage:', error)
      }
      return null
    }
  }

  /**
   * 期限切れキーのクリーンアップ
   */
  private async cleanupExpiredKeys(): Promise<void> {
    try {
      const now = Date.now()
      const allKeys = await this.getAllKeys()

      for (const key of allKeys) {
        if (key.expiresAt && key.expiresAt < now) {
          // キーを完全に削除
          await this.deleteKey(key.id)
          if (process.env.NODE_ENV === 'development') {
            logger.info(`Expired key cleaned up: ${key.id.substring(0, 8)}...`)
          }
        }
      }
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Key cleanup failed:', error)
      }
    }
  }

  /**
   * キーの削除
   */
  private async deleteKey(keyId: string): Promise<void> {
    if (this.redis) {
      await this.redis.del(`key:${keyId}`)
      await this.redis.zrem('keys:by_created', keyId)
    }

    this.keyCache.delete(keyId)
    this.keyUsageCounter.delete(keyId)
  }

  /**
   * 全キーの取得
   */
  private async getAllKeys(): Promise<KeyVersion[]> {
    const keys: KeyVersion[] = []

    if (this.redis) {
      const keyIds = await this.redis.zrange('keys:by_created', 0, -1)

      for (const keyId of keyIds) {
        const keyData = await this.redis.get(`key:${keyId}`)
        if (keyData) {
          keys.push(this.deserializeKey(keyData))
        }
      }
    } else {
      keys.push(...Array.from(this.keyCache.values()))
    }

    return keys
  }

  /**
   * キーのシリアライゼーション
   */
  private serializeKey(key: KeyVersion): string {
    return JSON.stringify({
      ...key,
      key: key.key.toString('hex'),
    })
  }

  /**
   * キーのデシリアライゼーション
   */
  private deserializeKey(data: string): KeyVersion {
    const parsed = JSON.parse(data)
    return {
      ...parsed,
      key: Buffer.from(parsed.key, 'hex'),
    }
  }

  /**
   * 特定のキーでデータ暗号化
   */
  private encryptWithKey(data: string, key: KeyVersion): string {
    const iv = crypto.randomBytes(16)
    const cipher = crypto.createCipher(key.algorithm, key.key)

    let encrypted = cipher.update(data, 'utf8', 'hex')
    encrypted += cipher.final('hex')

    return JSON.stringify({
      encrypted,
      iv: iv.toString('hex'),
      keyId: key.id,
    })
  }

  /**
   * 特定のキーでデータ復号化
   */
  private decryptWithKey(encryptedData: string, key: KeyVersion): string {
    const { encrypted } = JSON.parse(encryptedData)
    const decipher = crypto.createDecipher(key.algorithm, key.key)

    let decrypted = decipher.update(encrypted, 'hex', 'utf8')
    decrypted += decipher.final('utf8')

    return decrypted
  }

  /**
   * 再暗号化対象データの取得（実装は実際のデータベース構造に依存）
   */
  private async getDataForReEncryption(_oldKeyId: string, _limit: number): Promise<any[]> {
    // 実際の実装では、データベースクエリを実行
    // ここではダミーデータを返す
    return []
  }

  /**
   * 暗号化データの更新（実装は実際のデータベース構造に依存）
   */
  private async updateEncryptedData(
    dataId: string,
    newEncryptedData: string,
    newKeyId: string
  ): Promise<void> {
    // 実際の実装では、データベース更新を実行
    if (process.env.NODE_ENV === 'development') {
      logger.debug(`Updated data ${dataId} with new key ${newKeyId}`)
    }
  }

  /**
   * ローテーション統計の更新
   */
  private async updateRotationStatistics(): Promise<void> {
    try {
      if (this.redis) {
        await this.redis.incr('key_rotation_count')
        await this.redis.set('last_rotation_time', Date.now())
      }
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to update rotation statistics:', error)
      }
    }
  }

  /**
   * ローテーション履歴の取得
   */
  private async getRotationHistory(): Promise<
    Array<{ timestamp: number; keyId: string; action: string }>
  > {
    try {
      if (this.redis) {
        const history = await this.redis.lrange('key_rotation_history', 0, 9)
        return history.map((item) => JSON.parse(item))
      }
      return []
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to get rotation history:', error)
      }
      return []
    }
  }

  /**
   * セキュリティイベントログ記録
   */
  private async logSecurityEvent(event: string, details: unknown): Promise<void> {
    try {
      const logEntry = {
        event,
        details,
        timestamp: Date.now(),
      }

      if (this.redis) {
        await this.redis.lpush('security_events', JSON.stringify(logEntry))
        await this.redis.ltrim('security_events', 0, 999) // 最新1000件を保持
      }

      if (process.env.NODE_ENV === 'development') {
        logger.warn(`Security event logged: ${event}`, details)
      }
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to log security event:', error)
      }
    }
  }

  /**
   * HSM統合準備（将来実装）
   */
  private async prepareHSMIntegration(): Promise<void> {
    // HSM (Hardware Security Module) 統合の準備
    if (process.env.NODE_ENV === 'development') {
      logger.info('HSM integration preparation (placeholder)')
    }
  }

  /**
   * 分散キー管理設定
   */
  private async setupDistributedKeyManagement(): Promise<void> {
    // 分散環境でのキー管理設定
    if (process.env.NODE_ENV === 'development') {
      logger.info('Distributed key management setup (placeholder)')
    }
  }

  /**
   * キー監査ログ有効化
   */
  private async enableKeyAuditLogging(): Promise<void> {
    // キー使用の監査ログ機能を有効化
    if (process.env.NODE_ENV === 'development') {
      logger.info('Key audit logging enabled (placeholder)')
    }
  }

  /**
   * キーバックアップ戦略設定
   */
  private async setupKeyBackupStrategy(): Promise<void> {
    // 災害復旧用のキーバックアップ戦略を設定
    if (process.env.NODE_ENV === 'development') {
      logger.info('Key backup strategy setup (placeholder)')
    }
  }

  /**
   * システム終了処理
   */
  destroy(): void {
    if (this.rotationTimer) {
      clearInterval(this.rotationTimer)
      this.rotationTimer = null
    }

    if (process.env.NODE_ENV === 'development') {
      logger.info('Key Management System destroyed')
    }
  }
}

/**
 * 拡張された暗号化サービス（キーローテーション対応）
 */
export class EnhancedEncryptionService {
  private keyManager: KeyManagementSystem

  constructor(masterKey: string, config?: Partial<KeyRotationConfig>) {
    this.keyManager = new KeyManagementSystem(masterKey, config)
  }

  /**
   * データ暗号化（自動キーローテーション対応）
   */
  async encrypt(data: string): Promise<{
    encrypted: string
    iv: string
    tag: string
    metadata: EncryptionMetadata
  }> {
    try {
      const activeKey = await this.keyManager.getActiveEncryptionKey()
      const iv = crypto.randomBytes(16)

      const cipher = crypto.createCipher(activeKey.algorithm, activeKey.key)
      let encrypted = cipher.update(data, 'utf8', 'hex')
      encrypted += cipher.final('hex')

      const tag = cipher.getAuthTag?.()?.toString('hex') || ''

      const metadata: EncryptionMetadata = {
        keyId: activeKey.id,
        keyVersion: 1, // TODO: バージョニング実装
        algorithm: activeKey.algorithm,
        timestamp: Date.now(),
        rotationGeneration: 1, // TODO: 世代管理実装
      }

      return {
        encrypted,
        iv: iv.toString('hex'),
        tag,
        metadata,
      }
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Enhanced encryption failed:', error)
      }
      throw new Error('Encryption failed')
    }
  }

  /**
   * データ復号化（マルチバージョンキー対応）
   */
  async decrypt(
    encryptedData: string,
    iv: string,
    tag: string,
    metadata: EncryptionMetadata
  ): Promise<string> {
    try {
      const key = await this.keyManager.getKeyById(metadata.keyId)

      if (!key) {
        throw new Error(`Decryption key not found: ${metadata.keyId}`)
      }

      if (key.status === 'revoked') {
        throw new Error(`Cannot decrypt with revoked key: ${metadata.keyId}`)
      }

      const decipher = crypto.createDecipher(key.algorithm, key.key)

      if (tag) {
        decipher.setAuthTag?.(Buffer.from(tag, 'hex'))
      }

      let decrypted = decipher.update(encryptedData, 'hex', 'utf8')
      decrypted += decipher.final('utf8')

      return decrypted
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Enhanced decryption failed:', error)
      }
      throw new Error('Decryption failed')
    }
  }

  /**
   * キー管理システムへのアクセス
   */
  getKeyManager(): KeyManagementSystem {
    return this.keyManager
  }

  /**
   * システム終了処理
   */
  destroy(): void {
    this.keyManager.destroy()
  }
}

// 環境変数からキーマネージャーを初期化
