}

import { openDB, IDBPDatabase } from 'idb'
import { logger } from '../../services/logger'

export interface StorageItem {
  key: string
  value: unknown
  timestamp: number
  version?: string
  userId?: string
}

export interface StorageOptions {
  encrypt?: boolean
  compress?: boolean
  ttl?: number // Time to live in milliseconds
}

export class IndexedDBStorage {
  private dbPromise: Promise<IDBPDatabase> | null = null
  private readonly DB_NAME = 'PMPLearningStorage'
  private readonly DB_VERSION = 1
  private readonly STORE_NAME = 'keyval'

  constructor() {
    this.initDB()
  }

  /**
   * Initialize IndexedDB database
   */
  private async initDB(): Promise<IDBPDatabase> {
    if (!this.dbPromise) {
      this.dbPromise = openDB(this.DB_NAME, this.DB_VERSION, {
        upgrade(db) {
          // Create main key-value store
          if (!db.objectStoreNames.contains('keyval')) {
            const store = db.createObjectStore('keyval', {
              keyPath: 'key',
            })
            store.createIndex('timestamp', 'timestamp')
            store.createIndex('userId', 'userId')
            store.createIndex('version', 'version')
          }

          // Create sync queue store
          if (!db.objectStoreNames.contains('syncQueue')) {
            const syncStore = db.createObjectStore('syncQueue', {
              keyPath: 'id',
            })
            syncStore.createIndex('timestamp', 'timestamp')
            syncStore.createIndex('type', 'type')
            syncStore.createIndex('status', 'status')
          }

          // Create metadata store
          if (!db.objectStoreNames.contains('metadata')) {
            db.createObjectStore('metadata', {
              keyPath: 'key',
            })
          }
        },

        blocked() {
          if (process.env.NODE_ENV === 'development') {
            logger.warn('IndexedDB upgrade blocked')
          }
        },

        blocking() {
          if (process.env.NODE_ENV === 'development') {
            logger.warn('IndexedDB is blocking a newer version')
          }
        },
      })
    }

    return this.dbPromise
  }

  /**
   * Store an item in IndexedDB
   */
  async setItem(key: string, value: unknown, options: StorageOptions = {}): Promise<void> {
    try {
      const db = await this.initDB()

      const item: StorageItem = {
        key,
        value: options.compress ? this.compress(value) : value,
        timestamp: Date.now(),
        version: '2.0.0',
        userId: 'local-user', // Will be dynamic with auth
      }

      // Add TTL if specified
      if (options.ttl) {
        ;(item as any).expiresAt = Date.now() + options.ttl
      }

      const tx = db.transaction(this.STORE_NAME, 'readwrite')
      await tx.objectStore(this.STORE_NAME).put(item)
      await tx.complete
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error(`Failed to store item ${key}:`, error)
      }
      throw new Error(`Storage failed: ${error instanceof Error ? error.message : 'Unknown error'}`)
    }
  }

  /**
   * Retrieve an item from IndexedDB
   */
  async getItem<T>(key: string): Promise<T | null> {
    try {
      const db = await this.initDB()

      const tx = db.transaction(this.STORE_NAME, 'readonly')
      const item = await tx.objectStore(this.STORE_NAME).get(key)
      await tx.complete

      if (!item) {
        return null
      }

      // Check TTL
      if ((item as any).expiresAt && Date.now() > (item as any).expiresAt) {
        await this.removeItem(key)
        return null
      }

      return typeof item.value === 'string' && item.value.startsWith('compressed:')
        ? this.decompress(item.value)
        : item.value
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error(`Failed to retrieve item ${key}:`, error)
      }
      return null
    }
  }

  /**
   * Remove an item from IndexedDB
   */
  async removeItem(key: string): Promise<void> {
    try {
      const db = await this.initDB()

      const tx = db.transaction(this.STORE_NAME, 'readwrite')
      await tx.objectStore(this.STORE_NAME).delete(key)
      await tx.complete
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error(`Failed to remove item ${key}:`, error)
      }
      throw new Error(`Remove failed: ${error instanceof Error ? error.message : 'Unknown error'}`)
    }
  }

  /**
   * Get all keys
   */
  async keys(): Promise<string[]> {
    try {
      const db = await this.initDB()

      const tx = db.transaction(this.STORE_NAME, 'readonly')
      const keys = await tx.objectStore(this.STORE_NAME).getAllKeys()
      await tx.complete

      return keys as string[]
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to get keys:', error)
      }
      return []
    }
  }

  /**
   * Clear all data
   */
  async clear(): Promise<void> {
    try {
      const db = await this.initDB()

      const tx = db.transaction(this.STORE_NAME, 'readwrite')
      await tx.objectStore(this.STORE_NAME).clear()
      await tx.complete
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to clear storage:', error)
      }
      throw new Error(`Clear failed: ${error instanceof Error ? error.message : 'Unknown error'}`)
    }
  }

  /**
   * Get storage size estimate
   */
  async getStorageEstimate(): Promise<{ used: number; quota: number }> {
    try {
      if ('storage' in navigator && 'estimate' in navigator.storage) {
        const estimate = await navigator.storage.estimate()
        return {
          used: estimate.usage || 0,
          quota: estimate.quota || 0,
        }
      }

      return { used: 0, quota: 0 }
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to get storage estimate:', error)
      }
      return { used: 0, quota: 0 }
    }
  }

  /**
   * Get items by user ID
   */
  async getItemsByUser(userId: string): Promise<StorageItem[]> {
    try {
      const db = await this.initDB()

      const tx = db.transaction(this.STORE_NAME, 'readonly')
      const index = tx.objectStore(this.STORE_NAME).index('userId')
      const items = await index.getAll(userId)
      await tx.complete

      return items
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to get items by user:', error)
      }
      return []
    }
  }

  /**
   * Clean up expired items
   */
  async cleanup(): Promise<number> {
    try {
      const db = await this.initDB()
      const now = Date.now()
      let cleanedCount = 0

      const tx = db.transaction(this.STORE_NAME, 'readwrite')
      const store = tx.objectStore(this.STORE_NAME)
      const cursor = await store.openCursor()

      while (cursor) {
        const item = cursor.value
        if ((item as any).expiresAt && now > (item as any).expiresAt) {
          await cursor.delete()
          cleanedCount++
        }
        await cursor.continue()
      }

      await tx.complete
      return cleanedCount
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to cleanup expired items:', error)
      }
      return 0
    }
  }

  /**
   * Export data for backup
   */
  async exportData(): Promise<{ [key: string]: unknown }> {
    try {
      const db = await this.initDB()

      const tx = db.transaction(this.STORE_NAME, 'readonly')
      const items = await tx.objectStore(this.STORE_NAME).getAll()
      await tx.complete

      const exported: { [key: string]: unknown } = {}

      items.forEach((item) => {
        exported[item.key] = {
          value: item.value,
          timestamp: item.timestamp,
          version: item.version,
          userId: item.userId,
        }
      })

      return exported
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to export data:', error)
      }
      return {}
    }
  }

  /**
   * Import data from backup
   */
  async importData(data: { [key: string]: unknown }): Promise<number> {
    try {
      const db = await this.initDB()
      let importedCount = 0

      const tx = db.transaction(this.STORE_NAME, 'readwrite')
      const store = tx.objectStore(this.STORE_NAME)

      for (const [key, itemData] of Object.entries(data)) {
        const item: StorageItem = {
          key,
          value: itemData.value,
          timestamp: itemData.timestamp || Date.now(),
          version: itemData.version || '2.0.0',
          userId: itemData.userId || 'local-user',
        }

        await store.put(item)
        importedCount++
      }

      await tx.complete
      return importedCount
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to import data:', error)
      }
      throw new Error(`Import failed: ${error instanceof Error ? error.message : 'Unknown error'}`)
    }
  }

  /**
   * Simple compression using JSON and base64
   */
  private compress(data: unknown): string {
    try {
      const json = JSON.stringify(data)
      const compressed = btoa(encodeURIComponent(json))
      return `compressed:${compressed}`
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.warn('Compression failed, storing as-is:', error)
      }
      return data
    }
  }

  /**
   * Decompress data
   */
  private decompress(compressedData: string): unknown {
    try {
      if (!compressedData.startsWith('compressed:')) {
        return compressedData
      }

      const compressed = compressedData.slice('compressed:'.length)
      const json = decodeURIComponent(atob(compressed))
      return JSON.parse(json)
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.warn('Decompression failed:', error)
      }
      return compressedData
    }
  }

  /**
   * Check if IndexedDB is supported
   */
  static isSupported(): boolean {
    return typeof window !== 'undefined' && 'indexedDB' in window && indexedDB !== null
  }
}

// Fallback to localStorage if IndexedDB is not supported
export class FallbackStorage {
  async setItem(key: string, value: unknown): Promise<void> {
    try {
      localStorage.setItem(
        key,
        JSON.stringify({
          value,
          timestamp: Date.now(),
          version: '2.0.0',
        })
      )
    } catch (error) {
      throw new Error(
        `LocalStorage failed: ${error instanceof Error ? error.message : 'Unknown error'}`
      )
    }
  }

  async getItem<T>(key: string): Promise<T | null> {
    try {
      const item = localStorage.getItem(key)
      if (!item) return null

      const parsed = JSON.parse(item)
      return parsed.value
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error(`Failed to get item ${key}:`, error)
      }
      return null
    }
  }

  async removeItem(key: string): Promise<void> {
    localStorage.removeItem(key)
  }

  async keys(): Promise<string[]> {
    const keys: string[] = []
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if (key) keys.push(key)
    }
    return keys
  }

  async clear(): Promise<void> {
    localStorage.clear()
  }
}

export const storage = IndexedDBStorage.isSupported()
  ? new IndexedDBStorage()
  : new FallbackStorage()

import { z } from 'zod'
import { IndexedDBStorage } from './indexedDb'
import { SyncQueue } from './syncQueue'
import { logger } from '../../services/logger'

// Migration schemas for data validation
export const LegacyProgressSchema = z.object({
  processGroups: z.record(z.number()),
  knowledgeAreas: z.record(z.number()),
  processes: z.record(z.number()),
  totalStudyTime: z.number().optional(),
  lastUpdated: z.string().optional(),
})

export const LegacyExamResultSchema = z.object({
  examId: z.string(),
  score: z.number(),
  totalQuestions: z.number(),
  correctAnswers: z.number(),
  timeSpent: z.number(),
  knowledgeAreaScores: z.record(z.number()),
  completedAt: z.string(),
  answers: z.record(z.union([z.string(), z.number()])),
})

export const LegacyFlashCardSchema = z.object({
  processId: z.string(),
  confidence: z.number(),
  reviewCount: z.number(),
  lastReviewedAt: z.string(),
  nextReviewAt: z.string(),
})

export interface MigrationStatus {
  version: string
  completed: boolean
  errors: string[]
  progress: number
  startedAt?: string
  completedAt?: string
  backupCreated?: boolean
  dataValidated?: boolean
}

export interface MigrationReport {
  status: MigrationStatus
  migratedItems: {
    progress: number
    examResults: number
    flashCards: number
    settings: number
  }
  validationErrors: string[]
  warnings: string[]
}

export class MigrationService {
  private storage: IndexedDBStorage
  private syncQueue: SyncQueue
  private readonly CURRENT_VERSION = '2.0.0'
  private readonly MIGRATION_KEY = 'pmp-migration-status'

  constructor() {
    this.storage = new IndexedDBStorage()
    this.syncQueue = new SyncQueue()
  }

  /**
   * Get current migration status
   */
  async getMigrationStatus(): Promise<MigrationStatus> {
    try {
      const status = localStorage.getItem(this.MIGRATION_KEY)
      if (status) {
        return JSON.parse(status) as MigrationStatus
      }

      return {
        version: this.CURRENT_VERSION,
        completed: false,
        errors: [],
        progress: 0,
      }
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to get migration status:', error)
      }
      return {
        version: this.CURRENT_VERSION,
        completed: false,
        errors: [error instanceof Error ? error.message : 'Unknown error'],
        progress: 0,
      }
    }
  }

  /**
   * Update migration status
   */
  private async updateMigrationStatus(status: Partial<MigrationStatus>): Promise<void> {
    const currentStatus = await this.getMigrationStatus()
    const updatedStatus = { ...currentStatus, ...status }
    localStorage.setItem(this.MIGRATION_KEY, JSON.stringify(updatedStatus))
  }

  /**
   * Create backup of existing localStorage data
   */
  async createBackup(): Promise<boolean> {
    try {
      const backup: Record<string, any> = {}

      // Backup all PMP-related localStorage items
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i)
        if (
          key &&
          (key.includes('pmp-') || key.includes('learning-') || key.includes('progress-'))
        ) {
          backup[key] = localStorage.getItem(key)
        }
      }

      // Store backup in IndexedDB
      await this.storage.setItem('backup-' + Date.now(), backup)

      await this.updateMigrationStatus({
        backupCreated: true,
        progress: 10,
      })

      return true
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to create backup:', error)
      }
      await this.updateMigrationStatus({
        errors: [error instanceof Error ? error.message : 'Backup creation failed'],
      })
      return false
    }
  }

  /**
   * Validate localStorage data before migration
   */
  async validateLegacyData(): Promise<{ valid: boolean; errors: string[] }> {
    const errors: string[] = []

    try {
      // Validate progress data
      const progressData = localStorage.getItem('learning-progress')
      if (progressData) {
        try {
          const parsed = JSON.parse(progressData)
          LegacyProgressSchema.parse(parsed)
        } catch (err) {
          errors.push(
            `Invalid progress data: ${err instanceof Error ? err.message : 'Unknown error'}`
          )
        }
      }

      // Validate exam results
      const examResults = localStorage.getItem('exam-results')
      if (examResults) {
        try {
          const parsed = JSON.parse(examResults)
          if (Array.isArray(parsed)) {
            parsed.forEach((result, index) => {
              try {
                LegacyExamResultSchema.parse(result)
              } catch (err) {
                errors.push(
                  `Invalid exam result at index ${index}: ${err instanceof Error ? err.message : 'Unknown error'}`
                )
              }
            })
          }
        } catch (err) {
          errors.push(
            `Invalid exam results format: ${err instanceof Error ? err.message : 'Unknown error'}`
          )
        }
      }

      // Validate flashcard data
      const flashCardData = localStorage.getItem('flashcard-progress')
      if (flashCardData) {
        try {
          const parsed = JSON.parse(flashCardData)
          Object.entries(parsed).forEach(([key, value], _index) => {
            try {
              LegacyFlashCardSchema.parse(value)
            } catch (err) {
              errors.push(
                `Invalid flashcard data for ${key}: ${err instanceof Error ? err.message : 'Unknown error'}`
              )
            }
          })
        } catch (err) {
          errors.push(
            `Invalid flashcard data format: ${err instanceof Error ? err.message : 'Unknown error'}`
          )
        }
      }

      await this.updateMigrationStatus({
        dataValidated: true,
        progress: 20,
        errors: errors.length > 0 ? errors : [],
      })

      return { valid: errors.length === 0, errors }
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : 'Data validation failed'
      await this.updateMigrationStatus({
        errors: [errorMsg],
      })
      return { valid: false, errors: [errorMsg] }
    }
  }

  /**
   * Migrate learning progress data
   */
  private async migrateLearningProgress(): Promise<number> {
    try {
      const progressData = localStorage.getItem('learning-progress')
      if (!progressData) return 0

      const parsed = LegacyProgressSchema.parse(JSON.parse(progressData))

      // Transform to new format
      const modernProgress = {
        id: 'user-progress',
        userId: 'local-user',
        processGroups: parsed.processGroups,
        knowledgeAreas: parsed.knowledgeAreas,
        processes: parsed.processes,
        totalStudyTime: parsed.totalStudyTime || 0,
        lastUpdated: parsed.lastUpdated || new Date().toISOString(),
        version: this.CURRENT_VERSION,
        migratedFrom: 'localStorage',
        migratedAt: new Date().toISOString(),
      }

      await this.storage.setItem('learning-progress', modernProgress)
      await this.syncQueue.add('progress-update', modernProgress)

      return 1
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to migrate learning progress:', error)
      }
      throw error
    }
  }

  /**
   * Migrate exam results data
   */
  private async migrateExamResults(): Promise<number> {
    try {
      const examResults = localStorage.getItem('exam-results')
      if (!examResults) return 0

      const parsed = JSON.parse(examResults)
      const validResults = []

      if (Array.isArray(parsed)) {
        for (const result of parsed) {
          try {
            const validatedResult = LegacyExamResultSchema.parse(result)
            const modernResult = {
              ...validatedResult,
              id: `exam-${validatedResult.examId}-${Date.parse(validatedResult.completedAt)}`,
              userId: 'local-user',
              version: this.CURRENT_VERSION,
              migratedFrom: 'localStorage',
              migratedAt: new Date().toISOString(),
            }

            validResults.push(modernResult)
            await this.storage.setItem(`exam-result-${modernResult.id}`, modernResult)
            await this.syncQueue.add('exam-result-create', modernResult)
          } catch (err) {
            if (process.env.NODE_ENV === 'development') {
              logger.warn('Skipping invalid exam result:', err)
            }
          }
        }
      }

      return validResults.length
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to migrate exam results:', error)
      }
      throw error
    }
  }

  /**
   * Migrate flashcard progress data
   */
  private async migrateFlashCardProgress(): Promise<number> {
    try {
      const flashCardData = localStorage.getItem('flashcard-progress')
      if (!flashCardData) return 0

      const parsed = JSON.parse(flashCardData)
      const migratedCount = Object.keys(parsed).length

      for (const [processId, progress] of Object.entries(parsed)) {
        try {
          const validatedProgress = LegacyFlashCardSchema.parse(progress)
          const modernProgress = {
            ...validatedProgress,
            id: `flashcard-${processId}`,
            processId,
            userId: 'local-user',
            version: this.CURRENT_VERSION,
            migratedFrom: 'localStorage',
            migratedAt: new Date().toISOString(),
          }

          await this.storage.setItem(`flashcard-${processId}`, modernProgress)
          await this.syncQueue.add('flashcard-update', modernProgress)
        } catch (err) {
          if (process.env.NODE_ENV === 'development') {
            logger.warn(`Skipping invalid flashcard progress for ${processId}:`, err)
          }
        }
      }

      return migratedCount
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to migrate flashcard progress:', error)
      }
      throw error
    }
  }

  /**
   * Migrate user settings
   */
  private async migrateUserSettings(): Promise<number> {
    try {
      let migratedCount = 0
      const settingsKeys = [
        'theme-preference',
        'user-preferences',
        'customization-settings',
        'notification-settings',
      ]

      for (const key of settingsKeys) {
        const value = localStorage.getItem(key)
        if (value) {
          try {
            const parsed = JSON.parse(value)
            const modernSetting = {
              key,
              value: parsed,
              userId: 'local-user',
              version: this.CURRENT_VERSION,
              migratedFrom: 'localStorage',
              migratedAt: new Date().toISOString(),
            }

            await this.storage.setItem(key, modernSetting)
            await this.syncQueue.add('setting-update', modernSetting)
            migratedCount++
          } catch (err) {
            if (process.env.NODE_ENV === 'development') {
              logger.warn(`Failed to migrate setting ${key}:`, err)
            }
          }
        }
      }

      return migratedCount
    } catch (error) {
      if (process.env.NODE_ENV === 'development') {
        logger.error('Failed to migrate user settings:', error)
      }
      throw error
    }
  }

  /**
   * Main migration function
   */
  async migrateFromLocalStorage(): Promise<MigrationReport> {
    const startTime = new Date().toISOString()

    await this.updateMigrationStatus({
      startedAt: startTime,
      progress: 0,
    })

    try {
      // Step 1: Create backup
      const backupSuccess = await this.createBackup()
      if (!backupSuccess) {
        throw new Error('Failed to create backup')
      }

      // Step 2: Validate data
      const validation = await this.validateLegacyData()
      if (!validation.valid && validation.errors.length > 5) {
        throw new Error(
          `Too many validation errors: ${validation.errors.slice(0, 3).join(', ')}...`
        )
      }

      // Step 3: Migrate data
      const migratedItems = {
        progress: 0,
        examResults: 0,
        flashCards: 0,
        settings: 0,
      }

      try {
        migratedItems.progress = await this.migrateLearningProgress()
        await this.updateMigrationStatus({ progress: 40 })
      } catch (err) {
        validation.errors.push(
          `Progress migration failed: ${err instanceof Error ? err.message : 'Unknown error'}`
        )
      }

      try {
        migratedItems.examResults = await this.migrateExamResults()
        await this.updateMigrationStatus({ progress: 60 })
      } catch (err) {
        validation.errors.push(
          `Exam results migration failed: ${err instanceof Error ? err.message : 'Unknown error'}`
        )
      }

      try {
        migratedItems.flashCards = await this.migrateFlashCardProgress()
        await this.updateMigrationStatus({ progress: 80 })
      } catch (err) {
        validation.errors.push(
          `Flashcard migration failed: ${err instanceof Error ? err.message : 'Unknown error'}`
        )
      }

      try {
        migratedItems.settings = await this.migrateUserSettings()
        await this.updateMigrationStatus({ progress: 90 })
      } catch (err) {
        validation.errors.push(
          `Settings migration failed: ${err instanceof Error ? err.message : 'Unknown error'}`
        )
      }

      // Step 4: Complete migration
      const completedAt = new Date().toISOString()
      const finalStatus: MigrationStatus = {
        version: this.CURRENT_VERSION,
        completed: true,
        errors: validation.errors,
        progress: 100,
        startedAt: startTime,
        completedAt,
        backupCreated: true,
        dataValidated: true,
      }

      await this.updateMigrationStatus(finalStatus)

      return {
        status: finalStatus,
        migratedItems,
        validationErrors: validation.errors,
        warnings: [],
      }
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : 'Migration failed'
      const failedStatus: MigrationStatus = {
        version: this.CURRENT_VERSION,
        completed: false,
        errors: [errorMsg],
        progress: 0,
        startedAt: startTime,
      }

      await this.updateMigrationStatus(failedStatus)

      return {
        status: failedStatus,
        migratedItems: { progress: 0, examResults: 0, flashCards: 0, settings: 0 },
        validationErrors: [errorMsg],
        warnings: [],
      }
    }
  }

  /**
   * Check if migration is needed
   */
  async isMigrationNeeded(): Promise<boolean> {
    const status = await this.getMigrationStatus()

    if (status.completed) {
      return false
    }

    // Check if there's any legacy data to migrate
    const hasLegacyData = [
      'learning-progress',
      'exam-results',
      'flashcard-progress',
      'theme-preference',
    ].some((key) => localStorage.getItem(key) !== null)

    return hasLegacyData
  }

  /**
   * Reset migration status (for testing)
   */
  async resetMigration(): Promise<void> {
    localStorage.removeItem(this.MIGRATION_KEY)
    await this.storage.clear()
    await this.syncQueue.clear()
  }
}

export const _migrationService = new MigrationService()

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

/**
 * Format date to Japanese locale string
 */
export function formatDate(date: Date | string | null | undefined): string {
  if (!date) return ''

  const d = typeof date === 'string' ? new Date(date) : date

  return new Intl.DateTimeFormat('ja-JP', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  }).format(d)
}

/**
 * Format date and time to Japanese locale string
 */
export function formatDateTime(date: Date | string | null | undefined): string {
  if (!date) return ''

  const d = typeof date === 'string' ? new Date(date) : date

  return new Intl.DateTimeFormat('ja-JP', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  }).format(d)
}

/**
 * Format duration in minutes to human readable string
 */
export function formatDuration(minutes: number): string {
  if (minutes < 60) {
    return `${minutes}分`
  }

  const hours = Math.floor(minutes / 60)
  const mins = minutes % 60

  if (mins === 0) {
    return `${hours}時間`
  }

  return `${hours}時間${mins}分`
}

/**
 * Format percentage
 */
export function formatPercentage(value: number, decimals = 0): string {
  return `${(value * 100).toFixed(decimals)}%`
}

/**
 * Debounce function
 */
export function debounce<T extends (...args: unknown[]) => any>(
  func: T,
  delay: number
): (...args: Parameters<T>) => void {
  let timeoutId: NodeJS.Timeout

  return (...args: Parameters<T>) => {
    clearTimeout(timeoutId)
    timeoutId = setTimeout(() => func(...args), delay)
  }
}

/**
 * Throttle function
 */
export function throttle<T extends (...args: unknown[]) => any>(
  func: T,
  limit: number
): (...args: Parameters<T>) => void {
  let inThrottle: boolean

  return (...args: Parameters<T>) => {
    if (!inThrottle) {
      func(...args)
      inThrottle = true
      setTimeout(() => (inThrottle = false), limit)
    }
  }
}

/**
 * Sleep function for async delays
 */
export function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

/**
 * Generate random ID
 */
export function generateId(prefix = ''): string {
  const random = Math.random().toString(36).substring(2, 9)
  const timestamp = Date.now().toString(36)
  return prefix ? `${prefix}_${timestamp}_${random}` : `${timestamp}_${random}`
}

/**
 * Truncate text with ellipsis
 */
export function truncate(text: string, length: number): string {
  if (text.length <= length) return text
  return text.substring(0, length) + '...'
}

/**
 * Parse JSON safely
 */
export function safeJsonParse<T>(json: string, fallback: T): T {
  try {
    return JSON.parse(json)
  } catch {
    return fallback
  }
}

/**
 * Check if value is empty
 */
export function isEmpty(value: unknown): boolean {
  if (value == null) return true
  if (typeof value === 'string') return value.trim().length === 0
  if (Array.isArray(value)) return value.length === 0
  if (typeof value === 'object') return Object.keys(value).length === 0
  return false
}

/**
 * Group array by key
 */
export function groupBy<T>(array: T[], key: keyof T): Record<string, T[]> {
  return array.reduce(
    (result, item) => {
      const group = String(item[key])
      if (!result[group]) result[group] = []
      result[group].push(item)
      return result
    },
    {} as Record<string, T[]>
  )
}

/**
 * Sort array by multiple keys
 */
export function sortBy<T>(array: T[], keys: (keyof T)[]): T[] {
  return [...array].sort((a, b) => {
    for (const key of keys) {
      if (a[key] < b[key]) return -1
      if (a[key] > b[key]) return 1
    }
    return 0
  })
}

/**
 * Get initials from name
 */
export function getInitials(name: string): string {
  return name
    .split(' ')
    .map((word) => word[0])
    .join('')
    .toUpperCase()
    .slice(0, 2)
}

/**
 * RBAC (Role-Based Access Control) システムのテスト
 * Developer 1: 包括的認可システム（RBAC）実装のテスト
 */

import { describe, it, expect, beforeEach } from 'vitest'
import {
  PermissionChecker,
  createPermissionChecker,
  requirePermission,
  requireOwnership,
  Permission,
  Resource,
  Action,
  SubscriptionPlan,
  UserContext,
  PermissionError,
  getPermissionDebugInfo,
} from '../rbac'
import { UserRole } from '@prisma/client'

describe('RBAC システム', () => {
  describe('PermissionChecker', () => {
    let adminUser: UserContext
    let instructorUser: UserContext
    let premiumUser: UserContext
    let freeUser: UserContext

    beforeEach(() => {
      adminUser = {
        id: 'admin123',
        role: UserRole.ADMIN,
        subscriptionPlan: SubscriptionPlan.ENTERPRISE,
        subscriptionActive: true,
        profileComplete: true,
      }

      instructorUser = {
        id: 'instructor123',
        role: 'INSTRUCTOR' as any,
        subscriptionPlan: SubscriptionPlan.PREMIUM,
        subscriptionActive: true,
        profileComplete: true,
      }

      premiumUser = {
        id: 'user123',
        role: UserRole.USER,
        subscriptionPlan: SubscriptionPlan.PREMIUM,
        subscriptionActive: true,
        profileComplete: true,
      }

      freeUser = {
        id: 'user456',
        role: UserRole.USER,
        subscriptionPlan: SubscriptionPlan.FREE,
        subscriptionActive: false,
        profileComplete: true,
      }
    })

    describe('基本権限チェック', () => {
      it('管理者は全ての権限を持つ', () => {
        const checker = createPermissionChecker(adminUser)

        expect(checker.hasPermission(Permission.USER_ADMIN)).toBe(true)
        expect(checker.hasPermission(Permission.SYSTEM_ADMIN)).toBe(true)
        expect(checker.hasPermission(Permission.AI_UNLIMITED)).toBe(true)
        expect(checker.hasPermission(Permission.ANALYTICS_ADMIN)).toBe(true)
      })

      it('インストラクターは適切な権限を持つ', () => {
        const checker = createPermissionChecker(instructorUser)

        expect(checker.hasPermission(Permission.LEARNING_ANALYTICS)).toBe(true)
        expect(checker.hasPermission(Permission.EXAM_CREATE)).toBe(true)
        expect(checker.hasPermission(Permission.COLLAB_MODERATE)).toBe(true)
        expect(checker.hasPermission(Permission.AI_ADVANCED)).toBe(true)

        // 管理者専用権限は持たない
        expect(checker.hasPermission(Permission.SYSTEM_ADMIN)).toBe(false)
        expect(checker.hasPermission(Permission.USER_ADMIN)).toBe(false)
      })

      it('プレミアムユーザーは限定された権限を持つ', () => {
        const checker = createPermissionChecker(premiumUser)

        expect(checker.hasPermission(Permission.LEARNING_READ)).toBe(true)
        expect(checker.hasPermission(Permission.LEARNING_ANALYTICS)).toBe(true)
        expect(checker.hasPermission(Permission.AI_ADVANCED)).toBe(true)
        expect(checker.hasPermission(Permission.ANALYTICS_ADVANCED)).toBe(true)

        // 管理機能は持たない
        expect(checker.hasPermission(Permission.EXAM_CREATE)).toBe(false)
        expect(checker.hasPermission(Permission.CONTENT_WRITE)).toBe(false)
      })

      it('無料ユーザーは基本権限のみを持つ', () => {
        const checker = createPermissionChecker(freeUser)

        expect(checker.hasPermission(Permission.LEARNING_READ)).toBe(true)
        expect(checker.hasPermission(Permission.CONTENT_READ)).toBe(true)
        expect(checker.hasPermission(Permission.EXAM_TAKE)).toBe(true)

        // プレミアム機能は持たない
        expect(checker.hasPermission(Permission.AI_BASIC)).toBe(false)
        expect(checker.hasPermission(Permission.LEARNING_ANALYTICS)).toBe(false)
        expect(checker.hasPermission(Permission.LEARNING_EXPORT)).toBe(false)
      })
    })

    describe('複数権限チェック', () => {
      it('全ての権限が必要な場合（AND条件）', () => {
        const checker = createPermissionChecker(instructorUser)

        const requiredPermissions = [
          Permission.LEARNING_READ,
          Permission.LEARNING_WRITE,
          Permission.EXAM_CREATE,
        ]

        expect(checker.hasAllPermissions(requiredPermissions)).toBe(true)

        const impossiblePermissions = [
          Permission.LEARNING_READ,
          Permission.SYSTEM_ADMIN, // インストラクターには無い権限
        ]

        expect(checker.hasAllPermissions(impossiblePermissions)).toBe(false)
      })

      it('いずれかの権限があれば良い場合（OR条件）', () => {
        const checker = createPermissionChecker(freeUser)

        const anyPermissions = [
          Permission.AI_UNLIMITED, // 持っていない
          Permission.CONTENT_READ, // 持っている
          Permission.SYSTEM_ADMIN, // 持っていない
        ]

        expect(checker.hasAnyPermission(anyPermissions)).toBe(true)

        const noPermissions = [
          Permission.AI_UNLIMITED,
          Permission.SYSTEM_ADMIN,
          Permission.ANALYTICS_ADMIN,
        ]

        expect(checker.hasAnyPermission(noPermissions)).toBe(false)
      })
    })

    describe('リソース・アクションベースアクセス', () => {
      it('リソースとアクションの組み合わせで権限チェック', () => {
        const checker = createPermissionChecker(instructorUser)

        expect(checker.canAccess(Resource.LEARNING, Action.READ)).toBe(true)
        expect(checker.canAccess(Resource.LEARNING, Action.UPDATE)).toBe(true)
        expect(checker.canAccess(Resource.EXAM, Action.CREATE)).toBe(true)
        expect(checker.canAccess(Resource.SYSTEM, Action.ADMIN)).toBe(false)
      })
    })

    describe('条件付き権限チェック', () => {
      it('カスタム条件を含む権限チェック', () => {
        const checker = createPermissionChecker(premiumUser)

        const profileCompleteCondition = (ctx: UserContext) => ctx.profileComplete
        const profileIncompleteCondition = (ctx: UserContext) => !ctx.profileComplete

        expect(
          checker.canAccessWithCondition(Permission.LEARNING_ANALYTICS, profileCompleteCondition)
        ).toBe(true)

        expect(
          checker.canAccessWithCondition(Permission.LEARNING_ANALYTICS, profileIncompleteCondition)
        ).toBe(false)
      })
    })

    describe('リソース所有権チェック', () => {
      it('自分のリソースにはアクセス可能', () => {
        const checker = createPermissionChecker(freeUser)

        expect(checker.canAccessOwnResource(freeUser.id)).toBe(true)
        expect(checker.canAccessOwnResource('other-user-id')).toBe(false)
      })

      it('管理者は他人のリソースにもアクセス可能', () => {
        const checker = createPermissionChecker(adminUser)

        expect(checker.canAccessOwnResource('any-user-id')).toBe(true)
        expect(checker.canAccessOwnResource('another-user-id')).toBe(true)
      })
    })

    describe('特別なロールチェック', () => {
      it('管理者ロールの判定', () => {
        expect(createPermissionChecker(adminUser).isAdmin()).toBe(true)
        expect(createPermissionChecker(instructorUser).isAdmin()).toBe(false)
        expect(createPermissionChecker(premiumUser).isAdmin()).toBe(false)
      })

      it('インストラクターロールの判定', () => {
        expect(createPermissionChecker(adminUser).isInstructor()).toBe(true) // 管理者もインストラクター権限
        expect(createPermissionChecker(instructorUser).isInstructor()).toBe(true)
        expect(createPermissionChecker(premiumUser).isInstructor()).toBe(false)
      })

      it('プレミアムユーザーの判定', () => {
        expect(createPermissionChecker(premiumUser).isPremiumUser()).toBe(true)
        expect(createPermissionChecker(adminUser).isPremiumUser()).toBe(true) // エンタープライズもプレミアム
        expect(createPermissionChecker(freeUser).isPremiumUser()).toBe(false)
      })

      it('エンタープライズユーザーの判定', () => {
        expect(createPermissionChecker(adminUser).isEnterpriseUser()).toBe(true)
        expect(createPermissionChecker(premiumUser).isEnterpriseUser()).toBe(false)
        expect(createPermissionChecker(freeUser).isEnterpriseUser()).toBe(false)
      })
    })

    describe('AI機能使用権限', () => {
      it('基本AI機能の使用権限', () => {
        const basicUser = {
          ...freeUser,
          subscriptionPlan: SubscriptionPlan.BASIC,
          subscriptionActive: true,
        }
        const checker = createPermissionChecker(basicUser)

        expect(checker.canUseAI('basic')).toBe(true)
        expect(checker.canUseAI('advanced')).toBe(false)
        expect(checker.canUseAI('unlimited')).toBe(false)
      })

      it('高度なAI機能の使用権限', () => {
        const checker = createPermissionChecker(premiumUser)

        expect(checker.canUseAI('basic')).toBe(true)
        expect(checker.canUseAI('advanced')).toBe(true)
        expect(checker.canUseAI('unlimited')).toBe(false)
      })

      it('無制限AI機能の使用権限', () => {
        const checker = createPermissionChecker(adminUser)

        expect(checker.canUseAI('basic')).toBe(true)
        expect(checker.canUseAI('advanced')).toBe(true)
        expect(checker.canUseAI('unlimited')).toBe(true)
      })
    })

    describe('利用可能権限の取得', () => {
      it('ユーザーの利用可能権限リストを正しく取得', () => {
        const checker = createPermissionChecker(premiumUser)
        const availablePermissions = checker.getAvailablePermissions()

        expect(availablePermissions).toContain(Permission.LEARNING_READ)
        expect(availablePermissions).toContain(Permission.AI_ADVANCED)
        expect(availablePermissions).toContain(Permission.ANALYTICS_ADVANCED)
        expect(availablePermissions).not.toContain(Permission.SYSTEM_ADMIN)
        expect(availablePermissions).not.toContain(Permission.AI_UNLIMITED)
      })
    })
  })

  describe('ヘルパー関数', () => {
    describe('requirePermission', () => {
      const testUser: UserContext = {
        id: 'user123',
        role: UserRole.USER,
        subscriptionPlan: SubscriptionPlan.PREMIUM,
        subscriptionActive: true,
        profileComplete: true,
      }

      it('権限がある場合は成功', () => {
        const checker = requirePermission(Permission.LEARNING_READ)

        expect(() => checker(testUser)).not.toThrow()
      })

      it('権限がない場合はエラー', () => {
        const checker = requirePermission(Permission.SYSTEM_ADMIN)

        expect(() => checker(testUser)).toThrow('権限が不足しています')
      })

      it('複数権限のAND条件チェック', () => {
        const checker = requirePermission([Permission.LEARNING_READ, Permission.AI_ADVANCED], {
          mode: 'all',
        })

        expect(() => checker(testUser)).not.toThrow()
      })

      it('複数権限のOR条件チェック', () => {
        const checker = requirePermission(
          [
            Permission.SYSTEM_ADMIN, // 持っていない
            Permission.LEARNING_READ, // 持っている
          ],
          { mode: 'any' }
        )

        expect(() => checker(testUser)).not.toThrow()
      })

      it('未認証ユーザーは常にエラー', () => {
        const checker = requirePermission(Permission.LEARNING_READ)

        expect(() => checker(null)).toThrow('認証が必要です')
      })

      it('カスタムチェック機能', () => {
        const checker = requirePermission(Permission.LEARNING_READ, {
          customCheck: (ctx) => ctx.profileComplete,
        })

        expect(() => checker(testUser)).not.toThrow()

        const incompleteUser = { ...testUser, profileComplete: false }
        expect(() => checker(incompleteUser)).toThrow('カスタム権限チェックに失敗しました')
      })
    })

    describe('requireOwnership', () => {
      const testUser: UserContext = {
        id: 'user123',
        role: UserRole.USER,
        subscriptionPlan: SubscriptionPlan.FREE,
        subscriptionActive: false,
        profileComplete: true,
      }

      it('自分のリソースへのアクセスは成功', () => {
        const checker = requireOwnership('user123')

        expect(() => checker(testUser)).not.toThrow()
      })

      it('他人のリソースへのアクセスはエラー', () => {
        const checker = requireOwnership('other-user')

        expect(() => checker(testUser)).toThrow('リソースへのアクセス権限がありません')
      })

      it('管理者は他人のリソースにもアクセス可能', () => {
        const adminUser: UserContext = {
          id: 'admin123',
          role: UserRole.ADMIN,
          subscriptionPlan: SubscriptionPlan.ENTERPRISE,
          subscriptionActive: true,
          profileComplete: true,
        }

        const checker = requireOwnership('any-user')

        expect(() => checker(adminUser)).not.toThrow()
      })
    })
  })

  describe('デバッグ情報', () => {
    it('権限デバッグ情報を正しく生成', () => {
      const testUser: UserContext = {
        id: 'user123',
        role: UserRole.USER,
        subscriptionPlan: SubscriptionPlan.PREMIUM,
        subscriptionActive: true,
        profileComplete: true,
      }

      const debugInfo = getPermissionDebugInfo(testUser)

      expect(debugInfo.user.id).toBe('user123')
      expect(debugInfo.user.role).toBe(UserRole.USER)
      expect(debugInfo.user.subscriptionPlan).toBe(SubscriptionPlan.PREMIUM)
      expect(debugInfo.availablePermissions).toBeInstanceOf(Array)
      expect(debugInfo.rolePermissions).toBeInstanceOf(Array)
      expect(debugInfo.subscriptionPermissions).toBeInstanceOf(Array)
      expect(debugInfo.specialRoles).toHaveProperty('isAdmin')
      expect(debugInfo.specialRoles).toHaveProperty('isPremiumUser')
    })
  })

  describe('サブスクリプション無効時の動作', () => {
    it('サブスクリプションが無効な場合はFREEプランの権限のみ', () => {
      const inactiveUser: UserContext = {
        id: 'user123',
        role: UserRole.USER,
        subscriptionPlan: SubscriptionPlan.PREMIUM,
        subscriptionActive: false, // 無効
        profileComplete: true,
      }

      const checker = createPermissionChecker(inactiveUser)

      // 基本権限のみ
      expect(checker.hasPermission(Permission.LEARNING_READ)).toBe(true)
      expect(checker.hasPermission(Permission.CONTENT_READ)).toBe(true)

      // プレミアム機能は無効
      expect(checker.hasPermission(Permission.AI_ADVANCED)).toBe(false)
      expect(checker.hasPermission(Permission.ANALYTICS_ADVANCED)).toBe(false)
    })
  })
})

/**
 * Authentication Providers Configuration
 * NextAuth.js providers setup with Google, GitHub, and Credentials
 * 担当: 認証・セキュリティエンジニア
 */

import { NextAuthOptions } from 'next-auth'
import GoogleProvider from 'next-auth/providers/google'
import GitHubProvider from 'next-auth/providers/github'
import CredentialsProvider from 'next-auth/providers/credentials'
import { PrismaAdapter } from '@auth/prisma-adapter'
import { prisma } from '@/lib/db'
import bcrypt from 'bcryptjs'
import { z } from 'zod'
import { UserRole, SubscriptionPlan } from '@prisma/client'
import type { DefaultSession } from 'next-auth'
import { logger } from '../../services/logger'

// NextAuth型拡張
declare module 'next-auth' {
  interface Session extends DefaultSession {
    user: {
      id: string
      role: UserRole
      subscriptionPlan: SubscriptionPlan
      subscriptionActive: boolean
      profileComplete: boolean
    } & DefaultSession['user']
  }

  interface User {
    role: UserRole
    subscriptionPlan: SubscriptionPlan
    subscriptionActive: boolean
    profileComplete: boolean
  }
}

declare module 'next-auth/jwt' {
  interface JWT {
    role: UserRole
    subscriptionPlan: SubscriptionPlan
    subscriptionActive: boolean
    profileComplete: boolean
  }
}

// 入力検証スキーマ
const credentialsSchema = z.object({
  email: z.string().email('有効なメールアドレスを入力してください'),
  password: z
    .string()
    .min(8, 'パスワードは8文字以上である必要があります')
    .regex(
      /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/,
      'パスワードは大文字、小文字、数字、特殊文字を含む必要があります'
    ),
})

// パスワードハッシュ化ユーティリティ
export const _hashPassword = async (password: string): Promise<string> => {
  const saltRounds = 12
  return await bcrypt.hash(password, saltRounds)
}

// パスワード検証ユーティリティ
export const verifyPassword = async (
  password: string,
  hashedPassword: string
): Promise<boolean> => {
  return await bcrypt.compare(password, hashedPassword)
}

// ユーザー作成ユーティリティ
const createUserWithDefaults = async (userData: {
  email: string
  name?: string | null
  image?: string | null
  hashedPassword?: string
}) => {
  return await prisma.user.create({
    data: {
      email: userData.email,
      name: userData.name,
      image: userData.image,
      hashedPassword: userData.hashedPassword,
      role: UserRole.USER,
      subscriptionPlan: SubscriptionPlan.FREE,
      subscriptionActive: true,
      profileComplete: false,
      settings: {
        create: {
          theme: 'light',
          language: 'ja',
          notifications: {
            email: true,
            push: false,
            weekly_progress: true,
            exam_reminders: true,
          },
        },
      },
      learningProgress: {
        create: {
          totalStudyTime: 0,
          completedProcesses: [],
          currentStreak: 0,
          longestStreak: 0,
          lastActivityDate: new Date(),
        },
      },
    },
    include: {
      settings: true,
      learningProgress: true,
    },
  })
}

export const authOptions: NextAuthOptions = {
  adapter: PrismaAdapter(prisma) as any,

  providers: [
    // Google OAuth Provider
    GoogleProvider({
      clientId: process.env.GOOGLE_CLIENT_ID!,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET!,
      authorization: {
        params: {
          prompt: 'consent',
          access_type: 'offline',
          response_type: 'code',
        },
      },
    }),

    // GitHub OAuth Provider
    GitHubProvider({
      clientId: process.env.GITHUB_CLIENT_ID!,
      clientSecret: process.env.GITHUB_CLIENT_SECRET!,
    }),

    // Email/Password Credentials Provider
    CredentialsProvider({
      name: 'credentials',
      credentials: {
        email: {
          label: 'Email',
          type: 'email',
          placeholder: 'user@example.com',
        },
        password: {
          label: 'Password',
          type: 'password',
        },
      },
      async authorize(credentials) {
        try {
          // 入力検証
          const validatedCredentials = credentialsSchema.parse(credentials)

          // ユーザー検索
          const user = await prisma.user.findUnique({
            where: {
              email: validatedCredentials.email,
            },
            include: {
              settings: true,
              subscription: true,
            },
          })

          // ユーザーが存在しない、またはパスワードが設定されていない
          if (!user || !user.hashedPassword) {
            return null
          }

          // パスワード検証
          const isValidPassword = await verifyPassword(
            validatedCredentials.password,
            user.hashedPassword
          )

          if (!isValidPassword) {
            return null
          }

          // サブスクリプション状態確認
          const subscriptionActive =
            user.subscription?.status === 'active' ||
            user.subscriptionPlan === SubscriptionPlan.FREE

          return {
            id: user.id,
            email: user.email,
            name: user.name,
            image: user.image,
            role: user.role,
            subscriptionPlan: user.subscriptionPlan,
            subscriptionActive,
            profileComplete: user.profileComplete,
          }
        } catch (error) {
          if (process.env.NODE_ENV === 'development') {
            logger.error('認証エラー:', error)
          }
          return null
        }
      },
    }),
  ],

  session: {
    strategy: 'jwt',
    maxAge: 30 * 24 * 60 * 60, // 30日
    updateAge: 24 * 60 * 60, // 24時間
  },

  jwt: {
    maxAge: 30 * 24 * 60 * 60, // 30日
  },

  pages: {
    signIn: '/auth/signin',
    signUp: '/auth/signup',
    error: '/auth/error',
    verifyRequest: '/auth/verify-request',
    newUser: '/auth/new-user',
  },

  callbacks: {
    async signIn({ user, account, _profile, _email, _credentials }) {
      try {
        // OAuth プロバイダーの場合、既存ユーザーをチェック
        if (account?.provider !== 'credentials') {
          const existingUser = await prisma.user.findUnique({
            where: { email: user.email! },
          })

          // 新規ユーザーの場合、デフォルト設定で作成
          if (!existingUser) {
            await createUserWithDefaults({
              email: user.email!,
              name: user.name,
              image: user.image,
            })
          }
        }

        return true
      } catch (error) {
        if (process.env.NODE_ENV === 'development') {
          logger.error('サインインエラー:', error)
        }
        return false
      }
    },

    async jwt({ token, user, _account }) {
      // 初回ログイン時
      if (user) {
        token.role = user.role
        token.subscriptionPlan = user.subscriptionPlan
        token.subscriptionActive = user.subscriptionActive
        token.profileComplete = user.profileComplete
      }

      // トークン更新時にユーザー情報を最新化
      if (token.email) {
        try {
          const dbUser = await prisma.user.findUnique({
            where: { email: token.email },
            include: {
              subscription: true,
            },
          })

          if (dbUser) {
            token.role = dbUser.role
            token.subscriptionPlan = dbUser.subscriptionPlan
            token.subscriptionActive =
              dbUser.subscription?.status === 'active' ||
              dbUser.subscriptionPlan === SubscriptionPlan.FREE
            token.profileComplete = dbUser.profileComplete
          }
        } catch (error) {
          if (process.env.NODE_ENV === 'development') {
            logger.error('JWT更新エラー:', error)
          }
        }
      }

      return token
    },

    async session({ session, token }) {
      if (token) {
        session.user.id = token.sub!
        session.user.role = token.role
        session.user.subscriptionPlan = token.subscriptionPlan
        session.user.subscriptionActive = token.subscriptionActive
        session.user.profileComplete = token.profileComplete
      }

      return session
    },
  },

  events: {
    async signIn({ user, account, _profile, isNewUser }) {
      // ログイン記録
      await prisma.userActivity.create({
        data: {
          userId: user.id,
          action: 'SIGN_IN',
          details: {
            provider: account?.provider,
            isNewUser,
            ip: null, // Request IPは後でミドルウェアで設定
          },
        },
      })

      if (process.env.NODE_ENV === 'development') {
        logger.debug(`ユーザーサインイン: ${user.email} (${account?.provider})`)
      }
    },

    async signOut({ session, token }) {
      if (token?.sub) {
        // ログアウト記録
        await prisma.userActivity.create({
          data: {
            userId: token.sub,
            action: 'SIGN_OUT',
            details: {
              sessionDuration: null, // 後で計算
            },
          },
        })

        if (process.env.NODE_ENV === 'development') {
          logger.debug(`ユーザーサインアウト: ${session?.user?.email}`)
        }
      }
    },

    async createUser({ user }) {
      if (process.env.NODE_ENV === 'development') {
        logger.debug(`新規ユーザー作成: ${user.email}`)
      }
    },
  },

  debug: process.env.NODE_ENV === 'development',

  logger: {
    error(code, metadata) {
      if (process.env.NODE_ENV === 'development') {
        logger.error(`NextAuth Error [${code}]:`, metadata)
      }
    },
    warn(code) {
      if (process.env.NODE_ENV === 'development') {
        logger.warn(`NextAuth Warning [${code}]`)
      }
    },
    debug(code, metadata) {
      if (process.env.NODE_ENV === 'development') {
        console.debug(`NextAuth Debug [${code}]:`, metadata)
      }
    },
  },
}

