// ユーザーコンテキスト
export interface UserContext {
  id: string
  role: UserRole | 'INSTRUCTOR'
  subscriptionPlan: SubscriptionPlan
  subscriptionActive: boolean
  profileComplete: boolean
}

// 権限チェッククラス
export class PermissionChecker {
  private userContext: UserContext

  constructor(userContext: UserContext) {
    this.userContext = userContext
  }

  // 単一権限チェック
  hasPermission(permission: Permission): boolean {
    const rolePerms = rolePermissions[this.userContext.role] || []
    const subscriptionPerms = this.userContext.subscriptionActive
      ? subscriptionPermissions[this.userContext.subscriptionPlan] || []
      : subscriptionPermissions[SubscriptionPlan.FREE]

    return rolePerms.includes(permission) && subscriptionPerms.includes(permission)
  }

  // 複数権限チェック（AND条件）
  hasAllPermissions(permissions: Permission[]): boolean {
    return permissions.every((permission) => this.hasPermission(permission))
  }

  // 複数権限チェック（OR条件）
  hasAnyPermission(permissions: Permission[]): boolean {
    return permissions.some((permission) => this.hasPermission(permission))
  }

  // リソース・アクションベースの権限チェック
  canAccess(resource: Resource, action: Action): boolean {
    const permission = `${resource}:${action}` as Permission
    return this.hasPermission(permission)
  }

  // 条件付き権限チェック
  canAccessWithCondition(
    permission: Permission,
    condition: (context: UserContext) => boolean
  ): boolean {
    return this.hasPermission(permission) && condition(this.userContext)
  }

  // 自分のリソースアクセス権限
  canAccessOwnResource(resourceOwnerId: string): boolean {
    return this.userContext.id === resourceOwnerId || this.isAdmin()
  }

  // 管理者権限チェック
  isAdmin(): boolean {
    return this.userContext.role === UserRole.ADMIN
  }

  // インストラクター権限チェック
  isInstructor(): boolean {
    return (
      [UserRole.ADMIN].includes(this.userContext.role) ||
      this.userContext.role === ('INSTRUCTOR' as any)
    )
  }

  // プレミアムユーザーチェック
  isPremiumUser(): boolean {
    return (
      this.userContext.subscriptionActive &&
      [SubscriptionPlan.PREMIUM, SubscriptionPlan.ENTERPRISE].includes(
        this.userContext.subscriptionPlan
      )
    )
  }

  // エンタープライズユーザーチェック
  isEnterpriseUser(): boolean {
    return (
      this.userContext.subscriptionActive &&
      this.userContext.subscriptionPlan === SubscriptionPlan.ENTERPRISE
    )
  }

  // AI機能使用可能チェック
  canUseAI(level: 'basic' | 'advanced' | 'unlimited' = 'basic'): boolean {
    const permissionMap = {
      basic: Permission.AI_BASIC,
      advanced: Permission.AI_ADVANCED,
      unlimited: Permission.AI_UNLIMITED,
    }

    return this.hasPermission(permissionMap[level])
  }

  // 使用可能な権限一覧取得
  getAvailablePermissions(): Permission[] {
    const rolePerms = rolePermissions[this.userContext.role] || []
    const subscriptionPerms = this.userContext.subscriptionActive
      ? subscriptionPermissions[this.userContext.subscriptionPlan] || []
      : subscriptionPermissions[SubscriptionPlan.FREE]

    return rolePerms.filter((perm) => subscriptionPerms.includes(perm))
  }
}

// 権限チェッカーファクトリー
export const createPermissionChecker = (userContext: UserContext): PermissionChecker => {
  return new PermissionChecker(userContext)
}

// Express/Next.js用のミドルウェアヘルパー
export const requirePermission = (
  permission: Permission | Permission[],
  options: {
    mode?: 'all' | 'any'
    customCheck?: (context: UserContext) => boolean
  } = {}
) => {
  return (userContext: UserContext | null): boolean => {
    if (!userContext) {
      throw new Error('認証が必要です')
    }

    const checker = createPermissionChecker(userContext)
    const permissions = Array.isArray(permission) ? permission : [permission]

    let hasPermission = false

    if (options.mode === 'any') {
      hasPermission = checker.hasAnyPermission(permissions)
    } else {
      hasPermission = checker.hasAllPermissions(permissions)
    }

    if (!hasPermission) {
      throw new Error('権限が不足しています')
    }

    if (options.customCheck && !options.customCheck(userContext)) {
      throw new Error('カスタム権限チェックに失敗しました')
    }

    return true
  }
}

// リソース所有者チェック
export const requireOwnership = (resourceOwnerId: string) => {
  return (userContext: UserContext | null): boolean => {
    if (!userContext) {
      throw new Error('認証が必要です')
    }

    const checker = createPermissionChecker(userContext)

    if (!checker.canAccessOwnResource(resourceOwnerId)) {
      throw new Error('リソースへのアクセス権限がありません')
    }

    return true
  }
}

// 権限検証スキーマ（API入力検証用）
export const permissionValidationSchema = z.object({
  action: z.nativeEnum(Action),
  resource: z.nativeEnum(Resource),
  resourceId: z.string().optional(),
  conditions: z.record(z.any()).optional(),
})

export type PermissionValidation = z.infer<typeof permissionValidationSchema>

// 権限エラー
export class PermissionError extends Error {
  constructor(
    message: string,
    public permission: Permission | Permission[],
    public userContext?: UserContext
  ) {
    super(message)
    this.name = 'PermissionError'
  }
}

// 権限デバッグ情報
export const getPermissionDebugInfo = (userContext: UserContext) => {
  const checker = createPermissionChecker(userContext)

  return {
    user: {
      id: userContext.id,
      role: userContext.role,
      subscriptionPlan: userContext.subscriptionPlan,
      subscriptionActive: userContext.subscriptionActive,
    },
    availablePermissions: checker.getAvailablePermissions(),
    rolePermissions: rolePermissions[userContext.role] || [],
    subscriptionPermissions: userContext.subscriptionActive
      ? subscriptionPermissions[userContext.subscriptionPlan] || []
      : subscriptionPermissions[SubscriptionPlan.FREE],
    specialRoles: {
      isAdmin: checker.isAdmin(),
      isInstructor: checker.isInstructor(),
      isPremiumUser: checker.isPremiumUser(),
      isEnterpriseUser: checker.isEnterpriseUser(),
    },
  }
}

export default PermissionChecker

/**
 * Health Check System
 * Comprehensive health monitoring for all system components
 * 担当: DevOpsエンジニア
 */

import { prisma } from '@/lib/db'
import { StripeService } from '@/server/services/stripeService'
import { Logger } from '../monitoring/logger'
import { metrics } from '../monitoring/metrics'
import Redis from 'ioredis'
// import { z } from 'zod' // TODO: Will be used in future

// ヘルスチェック結果の型定義
export interface HealthCheckResult {
  status: 'healthy' | 'degraded' | 'unhealthy'
  timestamp: string
  responseTime: number
  details?: Record<string, any>
  error?: string
}

// システム全体のヘルス状態
export interface SystemHealth {
  status: 'healthy' | 'degraded' | 'unhealthy'
  timestamp: string
  uptime: number
  version: string
  environment: string
  checks: {
    database: HealthCheckResult
    redis: HealthCheckResult
    stripe: HealthCheckResult
    email: HealthCheckResult
    storage: HealthCheckResult
    external_apis: HealthCheckResult
    memory: HealthCheckResult
    cpu: HealthCheckResult
    disk: HealthCheckResult
  }
  summary: {
    total: number
    healthy: number
    degraded: number
    unhealthy: number
  }
}

// ヘルスチェック設定
const HEALTH_CHECK_TIMEOUT = 5000 // 5秒
const MEMORY_WARNING_THRESHOLD = 0.8 // メモリ使用率80%
const DISK_WARNING_THRESHOLD = 0.85 // ディスク使用率85%

// Redis接続（オプション）
let redisClient: Redis | null = null
try {
  if (process.env.REDIS_URL) {
    redisClient = new Redis(process.env.REDIS_URL, {
      connectTimeout: HEALTH_CHECK_TIMEOUT,
      commandTimeout: HEALTH_CHECK_TIMEOUT,
    })
  }
} catch (error) {
  Logger.warn('Redis接続の初期化に失敗しました', {
    error: error instanceof Error ? error.message : error,
  })
}

// ヘルスチェッククラス
export class HealthChecker {
  // データベースヘルスチェック
  static async checkDatabase(): Promise<HealthCheckResult> {
    const startTime = Date.now()

    try {
      // 基本接続チェック
      await Promise.race([
        prisma.$queryRaw`SELECT 1`,
        new Promise((_, reject) =>
          setTimeout(() => reject(new Error('Database timeout')), HEALTH_CHECK_TIMEOUT)
        ),
      ])

      // 接続プール情報取得（可能な場合）
      const connectionInfo = (await prisma.$queryRaw`SELECT 
        COUNT(*) as total_connections
      FROM pg_stat_activity 
      WHERE datname = current_database()`) as any[]

      const responseTime = Date.now() - startTime

      // パフォーマンステスト
      const testStartTime = Date.now()
      await prisma.user.count()
      const queryTime = Date.now() - testStartTime

      let status: 'healthy' | 'degraded' | 'unhealthy' = 'healthy'
      if (responseTime > 1000 || queryTime > 500) {
        status = 'degraded'
      }

      return {
        status,
        timestamp: new Date().toISOString(),
        responseTime,
        details: {
          connectionCount: connectionInfo[0]?.total_connections || 0,
          queryTime,
          provider: 'postgresql',
        },
      }
    } catch (error) {
      const responseTime = Date.now() - startTime
      Logger.error('データベースヘルスチェック失敗', error)

      return {
        status: 'unhealthy',
        timestamp: new Date().toISOString(),
        responseTime,
        error: error instanceof Error ? error.message : 'Database connection failed',
      }
    }
  }

  // Redisヘルスチェック
  static async checkRedis(): Promise<HealthCheckResult> {
    const startTime = Date.now()

    if (!redisClient) {
      return {
        status: 'healthy', // Redisは必須ではない
        timestamp: new Date().toISOString(),
        responseTime: 0,
        details: { message: 'Redis not configured' },
      }
    }

    try {
      // PING コマンドでレスポンステスト
      await Promise.race([
        redisClient.ping(),
        new Promise((_, reject) =>
          setTimeout(() => reject(new Error('Redis timeout')), HEALTH_CHECK_TIMEOUT)
        ),
      ])

      // メモリ使用量確認
      const info = await redisClient.info('memory')
      const memoryMatch = info.match(/used_memory:(\d+)/)
      const usedMemory = memoryMatch ? parseInt(memoryMatch[1]) : 0

      const responseTime = Date.now() - startTime

      let status: 'healthy' | 'degraded' | 'unhealthy' = 'healthy'
      if (responseTime > 100) {
        status = 'degraded'
      }

      return {
        status,
        timestamp: new Date().toISOString(),
        responseTime,
        details: {
          usedMemory,
          connected: true,
        },
      }
    } catch (error) {
      const responseTime = Date.now() - startTime
      Logger.error('Redisヘルスチェック失敗', error)

      return {
        status: 'unhealthy',
        timestamp: new Date().toISOString(),
        responseTime,
        error: error instanceof Error ? error.message : 'Redis connection failed',
      }
    }
  }

  // Stripeヘルスチェック
  static async checkStripe(): Promise<HealthCheckResult> {
    const startTime = Date.now()

    try {
      // Stripe APIのヘルスチェック（アカウント情報取得）
      await Promise.race([
        StripeService.stripe.accounts.retrieve(),
        new Promise((_, reject) =>
          setTimeout(() => reject(new Error('Stripe timeout')), HEALTH_CHECK_TIMEOUT)
        ),
      ])

      const responseTime = Date.now() - startTime

      let status: 'healthy' | 'degraded' | 'unhealthy' = 'healthy'
      if (responseTime > 2000) {
        status = 'degraded'
      }

      return {
        status,
        timestamp: new Date().toISOString(),
        responseTime,
        details: {
          service: 'stripe',
          apiVersion: '2023-10-16',
        },
      }
    } catch (error) {
      const responseTime = Date.now() - startTime
      Logger.error('Stripeヘルスチェック失敗', error)

      return {
        status: 'unhealthy',
        timestamp: new Date().toISOString(),
        responseTime,
        error: error instanceof Error ? error.message : 'Stripe API unavailable',
      }
    }
  }

  // メールサービスヘルスチェック
  static async checkEmail(): Promise<HealthCheckResult> {
    const startTime = Date.now()

    try {
      // SMTP接続確認（実際のメール送信はしない）
      const { EmailService } = await import('../services/emailService')
      const result = await Promise.race([
        EmailService.verifyConnection(),
        new Promise<{ success: boolean; error?: string }>((_, reject) =>
          setTimeout(() => reject(new Error('Email timeout')), HEALTH_CHECK_TIMEOUT)
        ),
      ])

      const responseTime = Date.now() - startTime

      return {
        status: result.success ? 'healthy' : 'unhealthy',
        timestamp: new Date().toISOString(),
        responseTime,
        details: {
          smtpHost: process.env.SMTP_HOST,
          port: process.env.SMTP_PORT,
        },
        error: result.error,
      }
    } catch (error) {
      const responseTime = Date.now() - startTime
      Logger.error('メールヘルスチェック失敗', error)

      return {
        status: 'unhealthy',
        timestamp: new Date().toISOString(),
        responseTime,
        error: error instanceof Error ? error.message : 'Email service unavailable',
      }
    }
  }

  // ストレージヘルスチェック
  static async checkStorage(): Promise<HealthCheckResult> {
    const startTime = Date.now()

    try {
      const fs = await import('fs/promises')
      const path = await import('path')

      // ログディレクトリの読み書きテスト
      const testDir = path.join(process.cwd(), 'logs')
      const testFile = path.join(testDir, '.health-check')

      // ディレクトリ作成（存在しない場合）
      await fs.mkdir(testDir, { recursive: true })

      // テストファイル書き込み
      await fs.writeFile(testFile, new Date().toISOString())

      // テストファイル読み込み
      //       const content = await fs.readFile(testFile, 'utf-8') // TODO: Will be used in future

      // テストファイル削除
      await fs.unlink(testFile)

      const responseTime = Date.now() - startTime

      // ディスク使用量チェック
      let diskUsage = 0
      try {
        //         const stats = await fs.stat(testDir) // TODO: Will be used in future
        // 実際のディスク使用量計算は環境に依存するため、簡易実装
        diskUsage = 0.5 // プレースホルダー
      } catch {
        // ディスク使用量取得失敗は警告レベル
      }

      let status: 'healthy' | 'degraded' | 'unhealthy' = 'healthy'
      if (diskUsage > DISK_WARNING_THRESHOLD) {
        status = 'degraded'
      }

      return {
        status,
        timestamp: new Date().toISOString(),
        responseTime,
        details: {
          writeable: true,
          readable: true,
          diskUsage,
          testPath: testDir,
        },
      }
    } catch (error) {
      const responseTime = Date.now() - startTime
      Logger.error('ストレージヘルスチェック失敗', error)

      return {
        status: 'unhealthy',
        timestamp: new Date().toISOString(),
        responseTime,
        error: error instanceof Error ? error.message : 'Storage unavailable',
      }
    }
  }

  // 外部API統合ヘルスチェック
  static async checkExternalApis(): Promise<HealthCheckResult> {
    const startTime = Date.now()
    const results: Record<string, any> = {}

    try {
      // 複数の外部APIを並行してチェック
      const checks = [
        // OpenAI API（AI機能用）
        this.checkOpenAI()
          .then((result) => ({ openai: result }))
          .catch((error) => ({ openai: { error: error.message } })),

        // その他の外部サービス（必要に応じて追加）
        // this.checkSlack().then(result => ({ slack: result })).catch(error => ({ slack: { error: error.message } })),
      ]

      const apiResults = await Promise.allSettled(
        checks.map((check) =>
          Promise.race([
            check,
            new Promise((_, reject) =>
              setTimeout(() => reject(new Error('API timeout')), HEALTH_CHECK_TIMEOUT)
            ),
          ])
        )
      )

      // 結果をマージ
      apiResults.forEach((result) => {
        if (result.status === 'fulfilled') {
          Object.assign(results, result.value)
        }
      })

      const responseTime = Date.now() - startTime

      // 全体的なステータス判定
      const hasUnhealthy = Object.values(results).some((result: unknown) => result.error)
      const status = hasUnhealthy ? 'degraded' : 'healthy'

      return {
        status,
        timestamp: new Date().toISOString(),
        responseTime,
        details: results,
      }
    } catch (error) {
      const responseTime = Date.now() - startTime
      Logger.error('外部APIヘルスチェック失敗', error)

      return {
        status: 'degraded', // 外部APIは完全失敗でもdegradedに留める
        timestamp: new Date().toISOString(),
        responseTime,
        error: error instanceof Error ? error.message : 'External APIs check failed',
        details: results,
      }
    }
  }

  // OpenAI APIヘルスチェック
  private static async checkOpenAI(): Promise<{ status: string; responseTime: number }> {
    if (!process.env.OPENAI_API_KEY) {
      return { status: 'not_configured', responseTime: 0 }
    }

    const startTime = Date.now()
    try {
      // OpenAI APIの簡単なリクエスト
      const response = await fetch('https://api.openai.com/v1/models', {
        headers: {
          Authorization: `Bearer ${process.env.OPENAI_API_KEY}`,
        },
      })

      const responseTime = Date.now() - startTime

      return {
        status: response.ok ? 'healthy' : 'unhealthy',
        responseTime,
      }
    } catch (error) {
      return {
        status: 'unhealthy',
        responseTime: Date.now() - startTime,
      }
    }
  }

  // メモリヘルスチェック
  static async checkMemory(): Promise<HealthCheckResult> {
    const startTime = Date.now()

    try {
      const memoryUsage = process.memoryUsage()
      const responseTime = Date.now() - startTime

      const heapUsageRatio = memoryUsage.heapUsed / memoryUsage.heapTotal
      const rss = memoryUsage.rss / (1024 * 1024) // MB
      const external = memoryUsage.external / (1024 * 1024) // MB

      let status: 'healthy' | 'degraded' | 'unhealthy' = 'healthy'
      if (heapUsageRatio > MEMORY_WARNING_THRESHOLD) {
        status = 'degraded'
      }
      if (heapUsageRatio > 0.95) {
        status = 'unhealthy'
      }

      return {
        status,
        timestamp: new Date().toISOString(),
        responseTime,
        details: {
          heapUsed: Math.round(memoryUsage.heapUsed / (1024 * 1024)), // MB
          heapTotal: Math.round(memoryUsage.heapTotal / (1024 * 1024)), // MB
          heapUsageRatio: Math.round(heapUsageRatio * 100) / 100,
          rss: Math.round(rss),
          external: Math.round(external),
        },
      }
    } catch (error) {
      const responseTime = Date.now() - startTime

      return {
        status: 'unhealthy',
        timestamp: new Date().toISOString(),
        responseTime,
        error: error instanceof Error ? error.message : 'Memory check failed',
      }
    }
  }

  // CPUヘルスチェック
  static async checkCpu(): Promise<HealthCheckResult> {
    const startTime = Date.now()

    try {
      const startUsage = process.cpuUsage()

      // 100ms待機してCPU使用率を測定
      await new Promise((resolve) => setTimeout(resolve, 100))

      const currentUsage = process.cpuUsage(startUsage)
      const responseTime = Date.now() - startTime

      const totalUsage = currentUsage.user + currentUsage.system
      const cpuPercent = (totalUsage / 1000000) * 10 // 100ms期間での使用率

      let status: 'healthy' | 'degraded' | 'unhealthy' = 'healthy'
      if (cpuPercent > 80) {
        status = 'degraded'
      }
      if (cpuPercent > 95) {
        status = 'unhealthy'
      }

      return {
        status,
        timestamp: new Date().toISOString(),
        responseTime,
        details: {
          user: Math.round(currentUsage.user / 1000), // μs を ms に変換
          system: Math.round(currentUsage.system / 1000),
          total: Math.round(totalUsage / 1000),
          percent: Math.round(cpuPercent * 100) / 100,
        },
      }
    } catch (error) {
      const responseTime = Date.now() - startTime

      return {
        status: 'unhealthy',
        timestamp: new Date().toISOString(),
        responseTime,
        error: error instanceof Error ? error.message : 'CPU check failed',
      }
    }
  }

  // ディスクヘルスチェック
  static async checkDisk(): Promise<HealthCheckResult> {
    const startTime = Date.now()

    try {
      const _fs = await import('_fs/promises')
      //       const path = require('path') // TODO: Will be used in future

      // 簡易的なディスク容量チェック
      //       const stats = await fs.stat(process.cwd()) // TODO: Will be used in future
      const responseTime = Date.now() - startTime

      // 実際の使用量計算は環境依存のため、プレースホルダー実装
      const diskUsage = 0.6 // 仮の値

      let status: 'healthy' | 'degraded' | 'unhealthy' = 'healthy'
      if (diskUsage > DISK_WARNING_THRESHOLD) {
        status = 'degraded'
      }
      if (diskUsage > 0.95) {
        status = 'unhealthy'
      }

      return {
        status,
        timestamp: new Date().toISOString(),
        responseTime,
        details: {
          usage: Math.round(diskUsage * 100) / 100,
          path: process.cwd(),
        },
      }
    } catch (error) {
      const responseTime = Date.now() - startTime

      return {
        status: 'unhealthy',
        timestamp: new Date().toISOString(),
        responseTime,
        error: error instanceof Error ? error.message : 'Disk check failed',
      }
    }
  }

  // 包括的ヘルスチェック
  static async performComprehensiveHealthCheck(): Promise<SystemHealth> {
    const startTime = Date.now()

    Logger.info('包括的ヘルスチェック開始')

    try {
      // 並行してヘルスチェックを実行
      const [database, redis, stripe, email, storage, external_apis, memory, cpu, disk] =
        await Promise.all([
          this.checkDatabase(),
          this.checkRedis(),
          this.checkStripe(),
          this.checkEmail(),
          this.checkStorage(),
          this.checkExternalApis(),
          this.checkMemory(),
          this.checkCpu(),
          this.checkDisk(),
        ])

      const checks = {
        database,
        redis,
        stripe,
        email,
        storage,
        external_apis,
        memory,
        cpu,
        disk,
      }

      // 全体的なステータス判定
      const results = Object.values(checks)
      const healthy = results.filter((r) => r.status === 'healthy').length
      const degraded = results.filter((r) => r.status === 'degraded').length
      const unhealthy = results.filter((r) => r.status === 'unhealthy').length

      let overallStatus: 'healthy' | 'degraded' | 'unhealthy' = 'healthy'

      if (unhealthy > 0) {
        overallStatus = 'unhealthy'
      } else if (degraded > 0) {
        overallStatus = 'degraded'
      }

      const systemHealth: SystemHealth = {
        status: overallStatus,
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        version: process.env.APP_VERSION || '1.0.0',
        environment: process.env.NODE_ENV || 'development',
        checks,
        summary: {
          total: results.length,
          healthy,
          degraded,
          unhealthy,
        },
      }

      const duration = Date.now() - startTime
      Logger.info('包括的ヘルスチェック完了', {
        duration,
        status: overallStatus,
        summary: systemHealth.summary,
      })

      // メトリクス記録
      metrics.health('system', overallStatus, {
        duration,
        healthy,
        degraded,
        unhealthy,
      })

      return systemHealth
    } catch (error) {
      Logger.error('包括的ヘルスチェック失敗', error)

      return {
        status: 'unhealthy',
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        version: process.env.APP_VERSION || '1.0.0',
        environment: process.env.NODE_ENV || 'development',
        checks: {} as any,
        summary: {
          total: 0,
          healthy: 0,
          degraded: 0,
          unhealthy: 1,
        },
      }
    }
  }

  // 軽量ヘルスチェック（レスポンス速度重視）
  static async performLightHealthCheck(): Promise<{
    status: 'healthy' | 'degraded' | 'unhealthy'
    timestamp: string
    responseTime: number
  }> {
    const startTime = Date.now()

    try {
      // 最低限のチェックのみ実行
      const [database, memory] = await Promise.all([this.checkDatabase(), this.checkMemory()])

      const responseTime = Date.now() - startTime

      let status: 'healthy' | 'degraded' | 'unhealthy' = 'healthy'

      if (database.status === 'unhealthy' || memory.status === 'unhealthy') {
        status = 'unhealthy'
      } else if (database.status === 'degraded' || memory.status === 'degraded') {
        status = 'degraded'
      }

      return {
        status,
        timestamp: new Date().toISOString(),
        responseTime,
      }
    } catch (error) {
      Logger.error('軽量ヘルスチェック失敗', error)

      return {
        status: 'unhealthy',
        timestamp: new Date().toISOString(),
        responseTime: Date.now() - startTime,
      }
    }
  }
}

export default HealthChecker

/**
 * Structured Logging System
 * Centralized logging with correlation IDs and structured data
 * 担当: DevOpsエンジニア
 */

import winston from 'winston'
import path from 'path'
import { AsyncLocalStorage } from 'async_hooks'

// ログレベル定義
export enum LogLevel {
  ERROR = 'error',
  WARN = 'warn',
  INFO = 'info',
  HTTP = 'http',
  VERBOSE = 'verbose',
  DEBUG = 'debug',
  SILLY = 'silly',
}

// ログコンテキスト型定義
export interface LogContext {
  correlationId: string
  userId?: string
  sessionId?: string
  requestId?: string
  userAgent?: string
  ip?: string
  route?: string
  method?: string
}

// ログエントリー型定義
export interface LogEntry {
  timestamp: string
  level: LogLevel
  message: string
  context?: LogContext
  metadata?: Record<string, any>
  error?: {
    name: string
    message: string
    stack?: string
    code?: string | number
  }
  performance?: {
    duration: number
    memory: NodeJS.MemoryUsage
    cpu?: number
  }
}

// 相関ID管理用AsyncLocalStorage
const asyncLocalStorage = new AsyncLocalStorage<LogContext>()

// カスタムログフォーマット
const customFormat = winston.format.combine(
  winston.format.timestamp({
    format: 'YYYY-MM-DD HH:mm:ss.SSS',
  }),
  winston.format.errors({ stack: true }),
  winston.format.json(),
  winston.format.printf((info) => {
    const context = asyncLocalStorage.getStore()
    const logEntry: LogEntry = {
      timestamp: info.timestamp,
      level: info.level as LogLevel,
      message: info.message,
      context,
      metadata: info.metadata,
      error: info.error,
      performance: info.performance,
    }

    return JSON.stringify(logEntry, null, process.env.NODE_ENV === 'development' ? 2 : 0)
  })
)

// Winston ロガー設定
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: customFormat,
  defaultMeta: {
    service: 'pmp-learning-management',
    version: process.env.APP_VERSION || '1.0.0',
    environment: process.env.NODE_ENV || 'development',
  },
  transports: [
    // コンソール出力
    new winston.transports.Console({
      format:
        process.env.NODE_ENV === 'development'
          ? winston.format.combine(winston.format.colorize(), winston.format.simple())
          : customFormat,
    }),

    // ファイル出力（エラーレベル）
    new winston.transports.File({
      filename: path.join(process.cwd(), 'logs', 'error.log'),
      level: 'error',
      maxsize: 50 * 1024 * 1024, // 50MB
      maxFiles: 10,
      tailable: true,
    }),

    // ファイル出力（全レベル）
    new winston.transports.File({
      filename: path.join(process.cwd(), 'logs', 'combined.log'),
      maxsize: 100 * 1024 * 1024, // 100MB
      maxFiles: 20,
      tailable: true,
    }),

    // HTTP アクセスログ
    new winston.transports.File({
      filename: path.join(process.cwd(), 'logs', 'access.log'),
      level: 'http',
      maxsize: 100 * 1024 * 1024, // 100MB
      maxFiles: 15,
      tailable: true,
    }),
  ],

  // 未処理の例外とPromise拒否をキャッチ
  exceptionHandlers: [
    new winston.transports.File({
      filename: path.join(process.cwd(), 'logs', 'exceptions.log'),
    }),
  ],
  rejectionHandlers: [
    new winston.transports.File({
      filename: path.join(process.cwd(), 'logs', 'rejections.log'),
    }),
  ],
})

// 本番環境では未処理例外で終了しない
if (process.env.NODE_ENV === 'production') {
  logger.exitOnError = false
}

// ロガークラス
export class Logger {
  // 相関IDを生成
  static generateCorrelationId(): string {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
  }

  // コンテキストを設定してコードを実行
  static withContext<T>(context: LogContext, fn: () => T): T {
    return asyncLocalStorage.run(context, fn)
  }

  // 現在のコンテキスト取得
  static getContext(): LogContext | undefined {
    return asyncLocalStorage.getStore()
  }

  // コンテキスト更新
  static updateContext(updates: Partial<LogContext>): void {
    const currentContext = asyncLocalStorage.getStore()
    if (currentContext) {
      Object.assign(currentContext, updates)
    }
  }

  // パフォーマンス測定を伴うログ
  static async withPerformance<T>(
    message: string,
    fn: () => Promise<T>,
    metadata?: Record<string, any>
  ): Promise<T> {
    const startTime = process.hrtime.bigint()
    //     const startMemory = process.memoryUsage() // TODO: Will be used in future

    try {
      const result = await fn()

      const endTime = process.hrtime.bigint()
      const duration = Number(endTime - startTime) / 1000000 // ナノ秒をミリ秒に変換

      logger.info(message, {
        metadata,
        performance: {
          duration: Math.round(duration * 100) / 100,
          memory: process.memoryUsage(),
        },
      })

      return result
    } catch (error) {
      const endTime = process.hrtime.bigint()
      const duration = Number(endTime - startTime) / 1000000

      this.error(message + ' (失敗)', error, {
        metadata,
        performance: {
          duration: Math.round(duration * 100) / 100,
          memory: process.memoryUsage(),
        },
      })

      throw error
    }
  }

  // ログレベル別メソッド
  static error(message: string, error?: Error | unknown, metadata?: Record<string, any>): void {
    const errorInfo =
      error instanceof Error
        ? {
            name: error.name,
            message: error.message,
            stack: error.stack,
            code: (error as any).code,
          }
        : error
          ? { message: String(error) }
          : undefined

    logger.error(message, { metadata, error: errorInfo })
  }

  static warn(message: string, metadata?: Record<string, any>): void {
    logger.warn(message, { metadata })
  }

  static info(message: string, metadata?: Record<string, any>): void {
    logger.info(message, { metadata })
  }

  static http(
    message: string,
    metadata?: {
      method?: string
      url?: string
      statusCode?: number
      responseTime?: number
      contentLength?: number
      userAgent?: string
      ip?: string
    }
  ): void {
    logger.http(message, { metadata })
  }

  static debug(message: string, metadata?: Record<string, any>): void {
    logger.debug(message, { metadata })
  }

  static verbose(message: string, metadata?: Record<string, any>): void {
    logger.verbose(message, { metadata })
  }

  // 構造化ログ
  static structured(level: LogLevel, event: string, data: Record<string, any>): void {
    logger.log(level, `[${event}]`, {
      metadata: {
        event,
        ...data,
      },
    })
  }

  // セキュリティイベントログ
  static security(
    event: string,
    severity: 'low' | 'medium' | 'high' | 'critical',
    details: Record<string, any>
  ): void {
    this.structured(LogLevel.WARN, 'SECURITY_EVENT', {
      event,
      severity,
      ...details,
    })
  }

  // ビジネスイベントログ
  static business(
    event: string,
    entityType: string,
    entityId: string,
    action: string,
    details?: Record<string, any>
  ): void {
    this.structured(LogLevel.INFO, 'BUSINESS_EVENT', {
      event,
      entityType,
      entityId,
      action,
      ...details,
    })
  }

  // システムヘルスログ
  static health(
    component: string,
    status: 'healthy' | 'degraded' | 'unhealthy',
    metrics?: Record<string, any>
  ): void {
    this.structured(LogLevel.INFO, 'HEALTH_CHECK', {
      component,
      status,
      metrics,
    })
  }

  // データベース操作ログ
  static database(
    operation: string,
    table: string,
    duration: number,
    recordCount?: number,
    error?: Error
  ): void {
    if (error) {
      this.structured(LogLevel.ERROR, 'DATABASE_ERROR', {
        operation,
        table,
        duration,
        recordCount,
        error: {
          name: error.name,
          message: error.message,
        },
      })
    } else {
      this.structured(LogLevel.DEBUG, 'DATABASE_OPERATION', {
        operation,
        table,
        duration,
        recordCount,
      })
    }
  }

  // 外部API呼び出しログ
  static externalApi(
    service: string,
    endpoint: string,
    method: string,
    statusCode: number,
    duration: number,
    error?: Error
  ): void {
    const level = error ? LogLevel.ERROR : statusCode >= 400 ? LogLevel.WARN : LogLevel.INFO

    this.structured(level, 'EXTERNAL_API_CALL', {
      service,
      endpoint,
      method,
      statusCode,
      duration,
      success: !error && statusCode < 400,
      error: error
        ? {
            name: error.name,
            message: error.message,
          }
        : undefined,
    })
  }

  // 認証イベントログ
  static auth(
    event: 'LOGIN' | 'LOGOUT' | 'LOGIN_FAILED' | 'PASSWORD_RESET' | 'ACCOUNT_LOCKED',
    userId: string | null,
    details?: Record<string, any>
  ): void {
    this.structured(LogLevel.INFO, 'AUTH_EVENT', {
      event,
      userId,
      ...details,
    })
  }

  // サブスクリプションイベントログ
  static subscription(
    event: 'CREATED' | 'UPDATED' | 'CANCELLED' | 'PAYMENT_FAILED',
    userId: string,
    planId: string,
    details?: Record<string, any>
  ): void {
    this.structured(LogLevel.INFO, 'SUBSCRIPTION_EVENT', {
      event,
      userId,
      planId,
      ...details,
    })
  }

  // 学習進捗イベントログ
  static learning(
    event: 'SESSION_STARTED' | 'SESSION_COMPLETED' | 'EXAM_TAKEN' | 'GOAL_ACHIEVED',
    userId: string,
    details?: Record<string, any>
  ): void {
    this.structured(LogLevel.INFO, 'LEARNING_EVENT', {
      event,
      userId,
      ...details,
    })
  }
}

// Express/Next.js用のリクエストログミドルウェア
export const requestLoggingMiddleware = (req: unknown, res: unknown, next: unknown) => {
  const startTime = Date.now()
  const correlationId = req.headers['x-correlation-id'] || Logger.generateCorrelationId()

  // レスポンスヘッダーに相関IDを追加
  res.setHeader('X-Correlation-ID', correlationId)

  const context: LogContext = {
    correlationId,
    requestId: req.headers['x-request-id'],
    userAgent: req.headers['user-agent'],
    ip: req.ip || req.connection.remoteAddress,
    route: req.route?.path,
    method: req.method,
  }

  // ユーザー情報が利用可能な場合
  if (req.user?.id) {
    context.userId = req.user.id
  }
  if (req.sessionID) {
    context.sessionId = req.sessionID
  }

  // レスポンス終了時のログ
  const originalSend = res.send
  res.send = function (data: unknown) {
    const duration = Date.now() - startTime
    const statusCode = res.statusCode

    Logger.http(`${req.method} ${req.originalUrl}`, {
      method: req.method,
      url: req.originalUrl,
      statusCode,
      responseTime: duration,
      contentLength: res.get('content-length'),
      userAgent: req.headers['user-agent'],
      ip: req.ip,
    })

    return originalSend.call(this, data)
  }

  // コンテキストを設定して次のミドルウェアを実行
  Logger.withContext(context, () => {
    next()
  })
}

// tRPC用のログミドルウェア
export const trpcLoggingMiddleware = () => {
  return async ({ path, type, next, ctx }: unknown) => {
    const correlationId = Logger.generateCorrelationId()
    const startTime = Date.now()

    const context: LogContext = {
      correlationId,
      userId: ctx?.session?.user?.id,
      route: path,
      method: type,
    }

    return Logger.withContext(context, async () => {
      try {
        const result = await next()

        const duration = Date.now() - startTime
        Logger.debug(`tRPC ${type} ${path}`, {
          duration,
          success: true,
        })

        return result
      } catch (error) {
        const duration = Date.now() - startTime
        Logger.error(`tRPC ${type} ${path} failed`, error, {
          duration,
          path,
          type,
        })
        throw error
      }
    })
  }
}

// ログレベル動的変更
export const setLogLevel = (level: LogLevel): void => {
  logger.level = level
  Logger.info(`ログレベルを ${level} に変更しました`)
}

// ログ統計情報取得
export const getLogStats = (): {
  transports: Array<{
    name: string
    level: string
    filename?: string
  }>
} => {
  return {
    transports: logger.transports.map((transport: unknown) => ({
      name: transport.name,
      level: transport.level,
      filename: transport.filename,
    })),
  }
}

