    })

    this.errorBudgetGauge = new client.Gauge({
      name: 'pmp_learning_error_budget_remaining',
      help: 'Remaining error budget (0-1)',
      labelNames: ['slo_id', 'time_window'],
      registers: [this.prometheusRegistry],
    })
  }

